// Fiqh of ṭahāra and ṣalāh across the four Sunni schools: water, najāsa, wuḍūʾ, ghusl, tayammum, masḥ, ḥayḍ/nifās, times, conditions, pillars, adhān, sahw, travel, Jumuʿa, ʿĪd, witr, janāza, congregation. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- Stage 1: ṭahāra ----------
  { id: "fqs-001", s: "fiqh", g: 1, d: 1, t: ["water-types", "taharah-basics"], src: "Ibn Qudāma, ʿUmdat al-Fiqh, Kitāb al-Ṭahāra, bāb al-miyāh",
    en: ["What is water called that is pure in itself and can also purify other things, for example for wuḍūʾ?", ["Ṭahūr (purifying)", "Najis (impure)", "Makrūh (disliked)", "Mukhaffaf (lightened)"], "Ṭahūr water is pure and purifying, so it lifts ritual impurity and removes najāsa. Water that is only ṭāhir is pure but cannot be used for wuḍūʾ, and najis water is impure."],
    de: ["Wie nennt man Wasser, das in sich rein ist und auch anderes reinigen kann, etwa für die Gebetswaschung (wuḍūʾ)?", ["Ṭahūr (reinigend)", "Naǧis (unrein)", "Makrūh (verpönt)", "Muḫaffaf (erleichtert)"], "Ṭahūr-Wasser ist rein und reinigend; es hebt die rituelle Unreinheit auf und entfernt Unreines. Wasser, das nur ṭāhir ist, ist zwar rein, eignet sich aber nicht für die Waschung."],
    ar: ["ما اسم الماء الطاهر في نفسه المطهِّر لغيره، كالماء الذي يُتوضأ به؟", ["الماء الطَّهور", "الماء النجس", "الماء المكروه", "الماء المخفَّف"], "الطَّهور هو الطاهر في نفسه المطهِّر لغيره، فيرفع الحدث ويزيل النجس، أما الطاهر غير الطهور فلا يرفع الحدث."] },

  { id: "fqs-002", s: "fiqh", g: 1, d: 1, t: ["wudu-nullifiers"], tr: ["ijma"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, nawāqiḍ al-wuḍūʾ",
    en: ["Which of the following breaks wuḍūʾ by agreement of all the schools?", ["Passing wind", "Touching one's spouse", "Eating cooked food", "Bleeding from a small cut"], "Anything exiting from the front or back passage, including wind, nullifies wuḍūʾ by consensus. Touching a spouse and bleeding are matters of disagreement, and eating cooked food does not break wuḍūʾ according to the schools."],
    de: ["Was bricht die Gebetswaschung nach Übereinstimmung aller Rechtsschulen?", ["Das Entweichen von Wind", "Die Berührung des Ehepartners", "Das Essen gekochter Speisen", "Blut aus einem kleinen Schnitt"], "Alles, was aus dem vorderen oder hinteren Ausgang austritt, auch Wind, bricht die Waschung nach Konsens. Berührung des Ehepartners und Blutung sind umstritten; gekochte Speisen brechen sie nach den Schulen nicht."],
    ar: ["أيّ هذه الأمور ينقض الوضوء باتفاق المذاهب؟", ["خروج الريح", "لمس الزوجة", "أكل ما مسّته النار", "خروج دم من جرح صغير"], "الخارج من السبيلين ومنه الريح ناقض بالإجماع، أما لمس المرأة وخروج الدم ففيهما خلاف، وأكل ما مسّته النار لا ينقض عند المذاهب الأربعة."] },

  { id: "fqs-003", s: "fiqh", g: 1, d: 1, t: ["wudu-sunan"], tr: ["ijma"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on repeating the washing",
    en: ["In wuḍūʾ, how many times must each limb be washed, and what is the sunna?", ["Once is obligatory, three times is sunna", "Three times is obligatory, five is sunna", "Twice is obligatory, three is sunna", "Once is obligatory, seven times is sunna"], "Washing each limb once fulfils the obligation; the Prophet ﷺ also washed twice and three times, and three is the sunna. Going beyond three is disliked."],
    de: ["Wie oft muss bei der Waschung jedes Glied gewaschen werden, und was ist Sunna?", ["Einmal ist Pflicht, dreimal ist Sunna", "Dreimal ist Pflicht, fünfmal ist Sunna", "Zweimal ist Pflicht, dreimal ist Sunna", "Einmal ist Pflicht, siebenmal ist Sunna"], "Einmaliges Waschen erfüllt die Pflicht; der Prophet ﷺ wusch auch zwei- und dreimal, und dreimal ist Sunna. Mehr als dreimal ist verpönt."],
    ar: ["كم مرة يجب غسل كل عضو في الوضوء، وما السنة؟", ["الواجب مرة والسنة ثلاث", "الواجب ثلاث والسنة خمس", "الواجب مرتان والسنة ثلاث", "الواجب مرة والسنة سبع"], "تجزئ الغسلة الواحدة، وقد توضأ النبي ﷺ مرة ومرتين وثلاثًا، والثلاث هي السنة، وتُكره الزيادة عليها."] },

  { id: "fqs-004", s: "fiqh", g: 1, d: 1, t: ["wudu-faraid", "quran-evidence"], v: "5:6", src: "Ibn Kathīr, Tafsīr, on 5:6",
    en: ["Which parts of the body does the verse shown name for wuḍūʾ?", ["Face, arms, head and feet", "Face, mouth, arms and feet", "Hands, face, ears and feet", "Face, arms, neck and feet"], "The verse orders washing the face, the arms up to the elbows and the feet up to the ankles, and wiping the head. Rinsing the mouth, the ears and the neck are not named in it."],
    de: ["Welche Körperteile nennt der gezeigte Vers für die Gebetswaschung?", ["Gesicht, Arme, Kopf und Füße", "Gesicht, Mund, Arme und Füße", "Hände, Gesicht, Ohren und Füße", "Gesicht, Arme, Nacken und Füße"], "Der Vers befiehlt das Waschen des Gesichts, der Arme bis zu den Ellbogen und der Füße bis zu den Knöcheln sowie das Bestreichen des Kopfes. Mund, Ohren und Nacken werden darin nicht genannt."],
    ar: ["ما الأعضاء التي ذكرتها الآية المعروضة في الوضوء؟", ["الوجه واليدان والرأس والرجلان", "الوجه والفم واليدان والرجلان", "الكفان والوجه والأذنان والرجلان", "الوجه واليدان والرقبة والرجلان"], "أمرت الآية بغسل الوجه واليدين إلى المرافق والرجلين إلى الكعبين ومسح الرأس، ولم تذكر الفم ولا الأذنين ولا الرقبة."] },

  { id: "fqs-005", s: "fiqh", g: 1, d: 2, t: ["ghusl"], tr: ["ijma"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ghusl",
    en: ["Which of the following makes ghusl obligatory by agreement of the schools?", ["The end of menstruation", "Attending the Friday prayer", "Washing a dead body", "The morning of ʿĪd"], "The end of ḥayḍ obliges a woman to perform ghusl by consensus. Ghusl for Jumuʿa and ʿĪd is sunna according to the majority, and ghusl after washing a corpse is recommended."],
    de: ["Was macht die Ganzkörperwaschung (ġusl) nach Übereinstimmung der Schulen zur Pflicht?", ["Das Ende der Menstruation", "Der Besuch des Freitagsgebets", "Das Waschen eines Verstorbenen", "Der Morgen des ʿĪd"], "Das Ende der Menstruation verpflichtet nach Konsens zum Ġusl. Ġusl für Freitag und ʿĪd ist nach der Mehrheit Sunna, nach dem Waschen eines Verstorbenen empfohlen."],
    ar: ["أيّ هذه الأمور يوجب الغسل باتفاق المذاهب؟", ["انقطاع دم الحيض", "حضور صلاة الجمعة", "تغسيل الميت", "صباح يوم العيد"], "انقطاع الحيض موجب للغسل بالإجماع، أما غسل الجمعة والعيد فسنة عند الجمهور، والغسل من تغسيل الميت مستحب."] },

  { id: "fqs-006", s: "fiqh", g: 1, d: 2, t: ["hayd-nifas"], tr: ["ijma"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥayḍ, hadith of ʿĀʾisha on making up fasts",
    en: ["What must a woman make up after her menstruation ends?", ["The missed fasts, but not the prayers", "The missed prayers, but not the fasts", "Both the prayers and the fasts", "Neither the prayers nor the fasts"], "According to the report of ʿĀʾisha in Ṣaḥīḥ Muslim, women were told to make up the fasts but not the prayers. This is agreed upon, and it spares her a heavy burden since prayers recur daily."],
    de: ["Was muss eine Frau nach dem Ende ihrer Menstruation nachholen?", ["Die versäumten Fasttage, nicht die Gebete", "Die versäumten Gebete, nicht die Fasttage", "Sowohl die Gebete als auch die Fasttage", "Weder die Gebete noch die Fasttage"], "Nach dem Bericht von ʿĀʾiša in Ṣaḥīḥ Muslim wurden die Frauen angewiesen, das Fasten nachzuholen, nicht aber das Gebet. Darüber herrscht Konsens; die täglich wiederkehrenden Gebete wären sonst eine große Last."],
    ar: ["ماذا تقضي المرأة بعد طهرها من الحيض؟", ["الصوم دون الصلاة", "الصلاة دون الصوم", "الصلاة والصوم معًا", "لا تقضي صلاة ولا صومًا"], "في حديث عائشة عند مسلم أنهن كنّ يؤمرن بقضاء الصوم ولا يؤمرن بقضاء الصلاة، وعليه الإجماع، لأن الصلاة تتكرر فيشق قضاؤها."] },

  { id: "fqs-007", s: "fiqh", g: 1, d: 2, t: ["masah-khuffayn"], tr: ["jumhur"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ṭahāra, hadith of ʿAlī on the duration of wiping",
    en: ["According to the majority of scholars, for how long may a traveller wipe over leather socks (khuffayn)?", ["Three days and nights", "One day and night", "Seven days and nights", "Until he returns home"], "In the hadith of ʿAlī in Ṣaḥīḥ Muslim, the Prophet ﷺ set three days and nights for the traveller and one day and night for the resident. The Ḥanafī, Shāfiʿī and Ḥanbalī schools follow this; the well-known Mālikī view sets no fixed limit."],
    de: ["Wie lange darf ein Reisender nach der Mehrheit der Gelehrten über Ledersocken (ḫuffain) streichen?", ["Drei Tage und Nächte", "Einen Tag und eine Nacht", "Sieben Tage und Nächte", "Bis er nach Hause zurückkehrt"], "Im Hadith von ʿAlī in Ṣaḥīḥ Muslim legte der Prophet ﷺ für den Reisenden drei Tage und Nächte und für den Ansässigen einen Tag und eine Nacht fest. Dem folgen Ḥanafiten, Šāfiʿiten und Ḥanbaliten; die bekannte mālikitische Ansicht setzt keine feste Frist."],
    ar: ["ما مدة المسح على الخفين للمسافر عند جمهور العلماء؟", ["ثلاثة أيام بلياليهن", "يوم وليلة", "سبعة أيام بلياليهن", "حتى يرجع إلى بلده"], "في حديث علي عند مسلم جعل النبي ﷺ ثلاثة أيام ولياليهن للمسافر ويومًا وليلة للمقيم، وبه قال الحنفية والشافعية والحنابلة، والمشهور عند المالكية عدم التوقيت."] },

  { id: "fqs-008", s: "fiqh", g: 1, d: 2, t: ["masah-khuffayn"], tr: ["jumhur"], src: "Abū Dāwūd, Sunan, Kitāb al-Ṭahāra, report of ʿAlī on wiping the top of the khuff",
    en: ["Which part of the khuff is wiped in masḥ?", ["The top of the foot covering", "The sole underneath", "The heel only", "The whole khuff all round"], "Masḥ is done on the top of the khuff, as ʿAlī reported, noting that reason alone would have suggested the underside. The obligatory part is the top; the schools do not require wiping the sole."],
    de: ["Welcher Teil des Ḫuff wird beim Bestreichen (masḥ) bestrichen?", ["Die Oberseite über dem Fuß", "Die Sohle an der Unterseite", "Nur die Ferse", "Der ganze Ḫuff ringsum"], "Bestrichen wird die Oberseite, wie ʿAlī berichtete, der anmerkte, dass der bloße Verstand eher die Unterseite nahegelegt hätte. Pflicht ist die Oberseite; das Bestreichen der Sohle verlangen die Schulen nicht."],
    ar: ["أيّ جزء من الخف يُمسح؟", ["ظاهر الخف", "باطن الخف من أسفل", "العقب وحده", "الخف كله من جميع جهاته"], "يُمسح ظاهر الخف كما روى علي رضي الله عنه وقال إن الرأي كان يقتضي مسح أسفله، فالواجب مسح الظاهر ولا تشترط المذاهب مسح الأسفل."] },

  { id: "fqs-009", s: "fiqh", g: 1, d: 2, t: ["istinja"], src: "Ibn Qudāma, ʿUmdat al-Fiqh, Kitāb al-Ṭahāra, bāb al-istinjāʾ",
    en: ["What does istijmār mean?", ["Cleaning after relieving oneself with stones or similar", "Washing the private parts with water only", "Wiping the head during wuḍūʾ", "Sprinkling water on impure clothing"], "Istijmār is cleaning the exit with stones or other suitable dry, pure material; istinjāʾ with water is the other method. Combining both is best."],
    de: ["Was bedeutet istiǧmār?", ["Die Reinigung nach der Notdurft mit Steinen o. Ä.", "Das Waschen der Scham nur mit Wasser", "Das Bestreichen des Kopfes bei der Waschung", "Das Besprengen unreiner Kleidung mit Wasser"], "Istiǧmār ist die Reinigung des Ausgangs mit Steinen oder anderem geeigneten, trockenen, reinen Material; die Reinigung mit Wasser ist die andere Methode. Beides zu verbinden ist am besten."],
    ar: ["ما معنى الاستجمار؟", ["إزالة الخارج بالحجارة ونحوها", "غسل الفرج بالماء وحده", "مسح الرأس في الوضوء", "رشّ الماء على الثوب النجس"], "الاستجمار إزالة أثر الخارج بالحجارة أو ما يقوم مقامها من جامد طاهر منقٍّ، والاستنجاء بالماء هو الطريقة الأخرى، والجمع بينهما أفضل."] },

  { id: "fqs-010", s: "fiqh", g: 1, d: 1, t: ["najasa"], tr: ["ijma"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra min al-najas",
    en: ["Which of these is impure (najis) by agreement of the scholars?", ["Human urine", "A Muslim's sweat", "Human saliva", "Tears"], "Human urine and faeces are najis by consensus. Sweat, saliva and tears of a living human are pure."],
    de: ["Was davon ist nach Übereinstimmung der Gelehrten unrein (naǧis)?", ["Menschlicher Urin", "Der Schweiß eines Muslims", "Menschlicher Speichel", "Tränen"], "Menschlicher Urin und Kot sind nach Konsens unrein. Schweiß, Speichel und Tränen eines lebenden Menschen sind rein."],
    ar: ["أيّ هذه الأشياء نجس باتفاق العلماء؟", ["بول الآدمي", "عرق المسلم", "ريق الإنسان", "الدموع"], "بول الآدمي وغائطه نجسان بالإجماع، أما عرق الإنسان الحي وريقه ودموعه فطاهرة."] },

  { id: "fqs-011", s: "fiqh", g: 1, d: 1, t: ["tayammum"], tr: ["ijma"], v: "4:43", src: "Ibn Qudāma, al-Mughnī, Kitāb al-Tayammum",
    en: ["According to the verse shown, when is tayammum (dry purification) allowed?", ["When water is not found or cannot be used", "Whenever water is cold", "Only on the day of Jumuʿa", "Whenever one is in a hurry"], "The verse permits tayammum for the sick and the traveller and whoever finds no water. Lack of water or inability to use it (illness, harm) is the basis; haste or mere discomfort is not."],
    de: ["Wann ist nach dem gezeigten Vers die Trockenreinigung (tayammum) erlaubt?", ["Wenn kein Wasser da ist oder es nicht benutzt werden kann", "Immer wenn das Wasser kalt ist", "Nur am Freitag", "Immer wenn man es eilig hat"], "Der Vers erlaubt Tayammum dem Kranken, dem Reisenden und dem, der kein Wasser findet. Grundlage ist das Fehlen von Wasser oder die Unfähigkeit, es zu benutzen; Eile oder bloße Unannehmlichkeit genügen nicht."],
    ar: ["متى يُشرع التيمم بحسب الآية المعروضة؟", ["عند فقد الماء أو العجز عن استعماله", "كلما كان الماء باردًا", "يوم الجمعة فقط", "عند الاستعجال"], "رخّصت الآية في التيمم للمريض والمسافر ومن لم يجد الماء، فمناطه فقد الماء أو العجز عن استعماله، لا العجلة ولا مجرد المشقة اليسيرة."] },

  { id: "fqs-012", s: "fiqh", g: 1, d: 2, t: ["tayammum"], tr: ["ijma"], src: "Ibn al-Mundhir, al-Ijmāʿ, Kitāb al-Tayammum",
    en: ["Someone who performed tayammum because no water was available later finds water before praying. What is the ruling?", ["His tayammum is void; he must use the water", "He may pray with his tayammum anyway", "He must perform both wuḍūʾ and tayammum", "He waits until the next prayer time"], "Tayammum is a substitute that ends once water can be used. Finding water before starting the prayer voids it by agreement."],
    de: ["Jemand hat mangels Wasser Tayammum gemacht und findet vor dem Gebet doch Wasser. Was gilt?", ["Sein Tayammum ist ungültig; er muss das Wasser benutzen", "Er darf trotzdem mit Tayammum beten", "Er muss Waschung und Tayammum machen", "Er wartet bis zur nächsten Gebetszeit"], "Tayammum ist ein Ersatz, der endet, sobald Wasser benutzt werden kann. Findet man vor Gebetsbeginn Wasser, wird es nach Übereinstimmung ungültig."],
    ar: ["تيمم رجل لعدم الماء ثم وجد الماء قبل أن يصلي، فما الحكم؟", ["بطل تيممه ولزمه استعمال الماء", "يصلي بتيممه مع وجود الماء", "يجمع بين الوضوء والتيمم", "ينتظر حتى وقت الصلاة التالية"], "التيمم بدل ينتهي بالقدرة على الماء، فوجود الماء قبل الدخول في الصلاة يبطله باتفاق."] },

  // ---------- Stage 1: ṣalāh ----------
  { id: "fqs-013", s: "fiqh", g: 1, d: 1, t: ["salah-basics"], tr: ["ijma"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ṣalāt, hadith of the Night Journey",
    en: ["How many obligatory prayers are there in a day and night?", ["Five", "Three", "Six", "Seven"], "Five prayers were made obligatory on the night of the Miʿrāj: Fajr, Ẓuhr, ʿAṣr, Maghrib and ʿIshāʾ. This is known by necessity in the religion."],
    de: ["Wie viele Pflichtgebete gibt es an einem Tag und einer Nacht?", ["Fünf", "Drei", "Sechs", "Sieben"], "In der Nacht der Himmelfahrt wurden fünf Gebete zur Pflicht: Faǧr, Ẓuhr, ʿAṣr, Maġrib und ʿIšāʾ. Das ist ein zwingend bekannter Teil der Religion."],
    ar: ["كم عدد الصلوات المفروضة في اليوم والليلة؟", ["خمس", "ثلاث", "ست", "سبع"], "فُرضت خمس صلوات ليلة المعراج: الفجر والظهر والعصر والمغرب والعشاء، وهذا معلوم من الدين بالضرورة."] },

  { id: "fqs-014", s: "fiqh", g: 1, d: 1, t: ["salah-basics"], tr: ["ijma"], src: "al-Qudūrī, al-Mukhtaṣar, Kitāb al-Ṣalāt",
    en: ["How many rakʿas does the Maghrib prayer have?", ["Three", "Two", "Four", "Five"], "Maghrib has three rakʿas, both at home and on a journey; it is never shortened."],
    de: ["Wie viele Rakʿas hat das Maġrib-Gebet?", ["Drei", "Zwei", "Vier", "Fünf"], "Maġrib hat drei Rakʿas, zu Hause wie auf Reisen; es wird nie verkürzt."],
    ar: ["كم ركعة صلاة المغرب؟", ["ثلاث", "ركعتان", "أربع", "خمس"], "المغرب ثلاث ركعات في الحضر والسفر، ولا تُقصر."] },

  { id: "fqs-015", s: "fiqh", g: 1, d: 1, t: ["prayer-times"], tr: ["ijma"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Masājid, hadith of ʿAbd Allāh ibn ʿAmr on the prayer times",
    en: ["When does the time of Ẓuhr begin?", ["When the sun passes its zenith", "At sunrise", "When the shadow equals the object", "At sunset"], "Ẓuhr begins at zawāl, when the sun has passed the middle of the sky. The shadow equalling the object marks the start of ʿAṣr according to the majority."],
    de: ["Wann beginnt die Zeit des Ẓuhr-Gebets?", ["Wenn die Sonne den Zenit überschritten hat", "Bei Sonnenaufgang", "Wenn der Schatten so lang ist wie der Gegenstand", "Bei Sonnenuntergang"], "Ẓuhr beginnt mit dem Zawāl, wenn die Sonne die Himmelsmitte überschritten hat. Ein Schatten gleich der Gegenstandslänge markiert nach der Mehrheit den Beginn von ʿAṣr."],
    ar: ["متى يدخل وقت الظهر؟", ["عند زوال الشمس", "عند طلوع الشمس", "إذا صار ظل الشيء مثله", "عند غروب الشمس"], "يدخل الظهر بزوال الشمس عن كبد السماء، أما مصير ظل الشيء مثله فهو أول العصر عند الجمهور."] },

  { id: "fqs-016", s: "fiqh", g: 1, d: 2, t: ["prayer-times"], tr: ["ijma"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣalāt, waqt al-ṣubḥ",
    en: ["With which dawn does the time of Fajr begin?", ["The true dawn spreading across the horizon", "The false dawn rising vertically", "Sunrise", "The last third of the night"], "Fajr begins with the true dawn (al-fajr al-ṣādiq), the light spreading along the horizon. The earlier vertical glow, the false dawn, has no ruling for prayer or fasting."],
    de: ["Mit welcher Morgendämmerung beginnt die Zeit des Faǧr?", ["Mit der echten Dämmerung, die sich am Horizont ausbreitet", "Mit der falschen Dämmerung, die senkrecht aufsteigt", "Mit dem Sonnenaufgang", "Mit dem letzten Drittel der Nacht"], "Faǧr beginnt mit der echten Dämmerung (al-faǧr aṣ-ṣādiq), dem Licht, das sich entlang des Horizonts ausbreitet. Der frühere senkrechte Schein, die falsche Dämmerung, ist für Gebet und Fasten ohne Bedeutung."],
    ar: ["بأيّ فجر يدخل وقت صلاة الصبح؟", ["الفجر الصادق المستطير في الأفق", "الفجر الكاذب المستطيل", "طلوع الشمس", "الثلث الأخير من الليل"], "يدخل وقت الصبح بالفجر الصادق المنتشر في الأفق، أما الفجر الكاذب المستطيل فلا يتعلق به حكم الصلاة ولا الصوم."] },

  { id: "fqs-017", s: "fiqh", g: 1, d: 2, t: ["salah-conditions"], src: "Ibn Qudāma, ʿUmdat al-Fiqh, Kitāb al-Ṣalāt, bāb shurūṭ al-ṣalāt",
    en: ["Which of these is a condition (sharṭ) of the prayer rather than a pillar inside it?", ["Facing the qibla", "Bowing (rukūʿ)", "Prostration (sujūd)", "Reciting al-Fātiḥa"], "Conditions must exist before and throughout the prayer: purity, covering the ʿawra, the time having entered, and facing the qibla. Rukūʿ, sujūd and recitation are acts within the prayer."],
    de: ["Was davon ist eine Bedingung (šarṭ) des Gebets und kein Pfeiler darin?", ["Die Ausrichtung zur Qibla", "Die Verbeugung (rukūʿ)", "Die Niederwerfung (suǧūd)", "Die Rezitation der Fātiḥa"], "Bedingungen müssen vor und während des Gebets bestehen: Reinheit, Bedeckung der ʿAura, Eintritt der Zeit und Ausrichtung zur Qibla. Rukūʿ, Suǧūd und Rezitation sind Handlungen im Gebet."],
    ar: ["أيّ هذه شرط للصلاة لا ركن فيها؟", ["استقبال القبلة", "الركوع", "السجود", "قراءة الفاتحة"], "الشروط تسبق الصلاة وتستمر فيها كالطهارة وستر العورة ودخول الوقت واستقبال القبلة، أما الركوع والسجود والقراءة فأفعال داخل الصلاة."] },

  { id: "fqs-018", s: "fiqh", g: 1, d: 1, t: ["adhan-iqama"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, on the institution of the adhān",
    en: ["Who was the Prophet's ﷺ first and best-known muʾadhdhin in Medina?", ["Bilāl ibn Rabāḥ", "Ibn Umm Maktūm", "Abū Maḥdhūra", "Saʿd al-Qaraẓ"], "Bilāl was the first to call the adhān in Medina. Ibn Umm Maktūm also called, especially for Fajr; Abū Maḥdhūra was muʾadhdhin in Mecca and Saʿd al-Qaraẓ at Qubāʾ."],
    de: ["Wer war der erste und bekannteste Gebetsrufer (muʾaḏḏin) des Propheten ﷺ in Medina?", ["Bilāl ibn Rabāḥ", "Ibn Umm Maktūm", "Abū Maḥḏūra", "Saʿd al-Qaraẓ"], "Bilāl rief als Erster in Medina den Adhān. Auch Ibn Umm Maktūm rief, besonders zum Faǧr; Abū Maḥḏūra war Muʾaḏḏin in Mekka und Saʿd al-Qaraẓ in Qubāʾ."],
    ar: ["مَن أول مؤذن للنبي ﷺ في المدينة وأشهرهم؟", ["بلال بن رباح", "ابن أم مكتوم", "أبو محذورة", "سعد القرظ"], "بلال أول من أذّن في المدينة، وكان ابن أم مكتوم يؤذن أيضًا ولا سيما للفجر، وأبو محذورة مؤذن مكة، وسعد القرظ مؤذن قباء."] },

  { id: "fqs-019", s: "fiqh", g: 1, d: 2, t: ["adhan-iqama"], tr: ["jumhur"], src: "Abū Dāwūd, Sunan, Kitāb al-Ṣalāt, bāb kayfa al-adhān",
    en: ["Which phrase is added in the adhān of Fajr only?", ["al-ṣalātu khayrun min al-nawm", "qad qāmati al-ṣalāh", "ḥayya ʿalā al-falāḥ", "lā ilāha illā Allāh"], "In the Fajr adhān, 'prayer is better than sleep' is said twice after ḥayya ʿalā al-falāḥ (al-tathwīb). Qad qāmati al-ṣalāh belongs to the iqāma, and the other phrases are in every adhān."],
    de: ["Welche Formel wird nur im Adhān des Faǧr hinzugefügt?", ["aṣ-ṣalātu ḫairun mina n-naum", "qad qāmati ṣ-ṣalāh", "ḥayya ʿalā l-falāḥ", "lā ilāha illā llāh"], "Im Faǧr-Adhān wird „Das Gebet ist besser als der Schlaf“ nach ḥayya ʿalā l-falāḥ zweimal gesagt (at-taṯwīb). Qad qāmati ṣ-ṣalāh gehört zur Iqāma, die übrigen Formeln zu jedem Adhān."],
    ar: ["ما العبارة التي تُزاد في أذان الفجر خاصة؟", ["الصلاة خير من النوم", "قد قامت الصلاة", "حيّ على الفلاح", "لا إله إلا الله"], "التثويب في أذان الفجر: الصلاة خير من النوم مرتين بعد الحيعلتين، أما قد قامت الصلاة فمن الإقامة، والباقي في كل أذان."] },

  { id: "fqs-020", s: "fiqh", g: 1, d: 2, t: ["qasr-jam"], tr: ["ijma"], src: "Ibn al-Mundhir, al-Ijmāʿ, Kitāb al-Ṣalāt, ṣalāt al-musāfir",
    en: ["Which prayers may be shortened (qaṣr) on a journey?", ["Only the four-rakʿa prayers", "All five prayers", "Only Fajr and Maghrib", "Only the night prayers"], "Ẓuhr, ʿAṣr and ʿIshāʾ are shortened from four to two rakʿas. Fajr and Maghrib are never shortened, by consensus."],
    de: ["Welche Gebete dürfen auf Reisen verkürzt werden (qaṣr)?", ["Nur die Gebete mit vier Rakʿas", "Alle fünf Gebete", "Nur Faǧr und Maġrib", "Nur die Nachtgebete"], "Ẓuhr, ʿAṣr und ʿIšāʾ werden von vier auf zwei Rakʿas verkürzt. Faǧr und Maġrib werden nach Konsens nie verkürzt."],
    ar: ["ما الصلوات التي تُقصر في السفر؟", ["الرباعية فقط", "الصلوات الخمس كلها", "الفجر والمغرب فقط", "صلوات الليل فقط"], "تُقصر الظهر والعصر والعشاء من أربع إلى ركعتين، ولا قصر في الفجر والمغرب بالإجماع."] },

  { id: "fqs-021", s: "fiqh", g: 1, d: 2, t: ["congregation"], tr: ["jumhur"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Adhān, hadith of Ibn ʿAbbās praying with the Prophet ﷺ at night",
    en: ["Where does a single male follower stand when praying behind an imam?", ["At the imam's right side", "At the imam's left side", "Directly behind the imam", "Two rows behind the imam"], "Ibn ʿAbbās stood at the Prophet's ﷺ left and was moved to his right. The schools therefore hold that one male follower stands at the imam's right."],
    de: ["Wo steht ein einzelner männlicher Betender hinter einem Imam?", ["An der rechten Seite des Imams", "An der linken Seite des Imams", "Direkt hinter dem Imam", "Zwei Reihen hinter dem Imam"], "Ibn ʿAbbās stellte sich links neben den Propheten ﷺ und wurde auf dessen rechte Seite geführt. Daher steht nach den Schulen ein einzelner Mann rechts vom Imam."],
    ar: ["أين يقف المأموم الواحد من الرجال مع الإمام؟", ["عن يمين الإمام", "عن يسار الإمام", "خلف الإمام مباشرة", "خلف الإمام بصفين"], "وقف ابن عباس عن يسار النبي ﷺ فأداره إلى يمينه، ولذلك قالت المذاهب إن الواحد يقف عن يمين الإمام."] },

  { id: "fqs-022", s: "fiqh", g: 1, d: 1, t: ["jumuah"], tr: ["ijma"], src: "al-Qudūrī, al-Mukhtaṣar, bāb ṣalāt al-jumuʿa",
    en: ["How many rakʿas is the Friday prayer (Jumuʿa)?", ["Two", "Four", "Three", "Six"], "Jumuʿa is two rakʿas, preceded by two sermons, and it takes the place of Ẓuhr for those who pray it."],
    de: ["Wie viele Rakʿas hat das Freitagsgebet (ǧumuʿa)?", ["Zwei", "Vier", "Drei", "Sechs"], "Die Ǧumuʿa hat zwei Rakʿas, vor denen zwei Predigten gehalten werden; sie tritt für die Teilnehmer an die Stelle von Ẓuhr."],
    ar: ["كم ركعة صلاة الجمعة؟", ["ركعتان", "أربع", "ثلاث", "ست"], "الجمعة ركعتان تسبقهما خطبتان، وتقوم مقام الظهر لمن صلاها."] },

  { id: "fqs-023", s: "fiqh", g: 1, d: 2, t: ["jumuah"], tr: ["jumhur"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Jumuʿa, on who is obliged",
    en: ["On whom is the Friday prayer not obligatory according to the four schools?", ["A traveller", "A resident adult man", "A healthy free man", "A man living near the mosque"], "Jumuʿa is obligatory on the free, adult, sane, resident male without an excuse. A traveller is not obliged, though his Jumuʿa is valid if he attends, and it replaces his Ẓuhr."],
    de: ["Für wen ist das Freitagsgebet nach den vier Schulen keine Pflicht?", ["Für einen Reisenden", "Für einen ansässigen erwachsenen Mann", "Für einen gesunden freien Mann", "Für einen Mann nahe der Moschee"], "Die Ǧumuʿa ist Pflicht für den freien, erwachsenen, verständigen, ansässigen Mann ohne Entschuldigung. Der Reisende ist nicht verpflichtet; nimmt er teil, ist sie gültig und ersetzt sein Ẓuhr."],
    ar: ["على مَن لا تجب الجمعة عند المذاهب الأربعة؟", ["المسافر", "الرجل البالغ المقيم", "الرجل الحر الصحيح", "الرجل الساكن قرب المسجد"], "تجب الجمعة على الذكر الحر البالغ العاقل المقيم بلا عذر، ولا تجب على المسافر، فإن حضرها صحّت منه وأجزأته عن الظهر."] },

  { id: "fqs-024", s: "fiqh", g: 1, d: 1, t: ["janazah"], tr: ["ijma"], src: "Ibn Qudāma, ʿUmdat al-Fiqh, Kitāb al-Janāʾiz",
    en: ["Which of these is not part of the funeral prayer (ṣalāt al-janāza)?", ["Bowing and prostration", "Saying takbīr", "Supplication for the deceased", "Standing"], "The funeral prayer is performed standing with takbīrs and supplications; it has no rukūʿ and no sujūd."],
    de: ["Was gehört nicht zum Totengebet (ṣalāt al-ǧanāza)?", ["Verbeugung und Niederwerfung", "Das Sprechen des Takbīr", "Das Bittgebet für den Verstorbenen", "Das Stehen"], "Das Totengebet wird stehend mit Takbīrs und Bittgebeten verrichtet; es hat weder Rukūʿ noch Suǧūd."],
    ar: ["أيّ هذه ليس من صلاة الجنازة؟", ["الركوع والسجود", "التكبير", "الدعاء للميت", "القيام"], "صلاة الجنازة تُؤدّى قيامًا بتكبيرات وأدعية، ولا ركوع فيها ولا سجود."] },

  { id: "fqs-025", s: "fiqh", g: 1, d: 2, t: ["janazah"], tr: ["jumhur"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Janāʾiz, number of takbīrs",
    en: ["How many takbīrs does the funeral prayer have according to the four schools?", ["Four", "Three", "Five", "Seven"], "The four schools hold that the funeral prayer has four takbīrs. Some Companions are reported to have said five, but the practice settled on four."],
    de: ["Wie viele Takbīrs hat das Totengebet nach den vier Schulen?", ["Vier", "Drei", "Fünf", "Sieben"], "Nach den vier Schulen hat das Totengebet vier Takbīrs. Von einigen Gefährten werden fünf berichtet, die Praxis festigte sich aber auf vier."],
    ar: ["كم تكبيرة في صلاة الجنازة عند المذاهب الأربعة؟", ["أربع", "ثلاث", "خمس", "سبع"], "صلاة الجنازة أربع تكبيرات عند المذاهب الأربعة، ورُوي عن بعض الصحابة خمس، واستقر العمل على الأربع."] },

  // ---------- Stage 2: ṭahāra ----------
  { id: "fqs-026", s: "fiqh", g: 2, d: 2, t: ["wudu-faraid", "madhhab-comparison"], tr: ["hanafi"], src: "al-Qudūrī, al-Mukhtaṣar, Kitāb al-Ṭahāra",
    en: ["According to the Ḥanafī school, how many obligatory acts (farāʾiḍ) does wuḍūʾ have?", ["Four", "Six", "Seven", "Five"], "For the Ḥanafīs the farāʾiḍ are exactly the four acts in the verse: washing the face, the arms with the elbows, the feet with the ankles, and wiping a quarter of the head. Intention, order and continuity are sunna for them."],
    de: ["Wie viele Pflichthandlungen (farāʾiḍ) hat die Waschung nach der ḥanafitischen Schule?", ["Vier", "Sechs", "Sieben", "Fünf"], "Für die Ḥanafiten sind die Pflichten genau die vier Handlungen des Verses: Gesicht, Arme mit Ellbogen und Füße mit Knöcheln waschen sowie ein Viertel des Kopfes bestreichen. Absicht, Reihenfolge und Zügigkeit sind bei ihnen Sunna."],
    ar: ["كم فرائض الوضوء عند الحنفية؟", ["أربعة", "ستة", "سبعة", "خمسة"], "فرائض الوضوء عند الحنفية أربعة هي ما في الآية: غسل الوجه واليدين مع المرفقين والرجلين مع الكعبين ومسح ربع الرأس، والنية والترتيب والموالاة عندهم سنن."] },

  { id: "fqs-027", s: "fiqh", g: 2, d: 3, t: ["wudu-faraid", "madhhab-comparison"], tr: ["shafii"], src: "al-Nawawī, Minhāj al-Ṭālibīn, Kitāb al-Ṭahāra, bāb al-wuḍūʾ",
    en: ["According to the Shāfiʿī school, which two acts are added to the four of the verse to make six farāʾiḍ of wuḍūʾ?", ["Intention and order", "Intention and rubbing", "Order and continuity", "Rinsing the mouth and nose"], "Al-Nawawī lists six: intention, face, arms, wiping part of the head, feet, and tartīb. Rubbing (dalk) and continuity are obligatory for the Mālikīs, and rinsing mouth and nose is sunna for the Shāfiʿīs."],
    de: ["Welche zwei Handlungen fügt die šāfiʿitische Schule den vier des Verses hinzu, sodass sechs Pflichten der Waschung entstehen?", ["Absicht und Reihenfolge", "Absicht und Reiben", "Reihenfolge und Zügigkeit", "Mund- und Nasenspülung"], "An-Nawawī nennt sechs: Absicht, Gesicht, Arme, Bestreichen eines Teils des Kopfes, Füße und Reihenfolge. Reiben (dalk) und Zügigkeit sind bei den Mālikiten Pflicht, Mund- und Nasenspülung bei den Šāfiʿiten Sunna."],
    ar: ["ما الفرضان اللذان يزيدهما الشافعية على الأربعة التي في الآية فتصير فروض الوضوء ستة؟", ["النية والترتيب", "النية والدلك", "الترتيب والموالاة", "المضمضة والاستنشاق"], "عدّ النووي الفروض ستة: النية وغسل الوجه واليدين ومسح بعض الرأس وغسل الرجلين والترتيب، أما الدلك والموالاة فواجبان عند المالكية، والمضمضة والاستنشاق سنتان عند الشافعية."] },

  { id: "fqs-028", s: "fiqh", g: 2, d: 3, t: ["wudu-faraid", "madhhab-comparison"], tr: ["maliki"], src: "Khalīl ibn Isḥāq, al-Mukhtaṣar, farāʾiḍ al-wuḍūʾ",
    en: ["Which act is an obligatory part of wuḍūʾ in the Mālikī school but not in the other three?", ["Rubbing the limbs (dalk)", "Intention (niyya)", "Washing the feet", "Wiping the head"], "Khalīl lists seven farāʾiḍ, including dalk, passing the hand over the washed limb, and fawr (continuity). Dalk is not obligatory in wuḍūʾ for the Ḥanafīs, Shāfiʿīs or Ḥanbalīs."],
    de: ["Welche Handlung ist bei den Mālikiten Pflicht der Waschung, bei den anderen drei Schulen aber nicht?", ["Das Reiben der Glieder (dalk)", "Die Absicht (nīya)", "Das Waschen der Füße", "Das Bestreichen des Kopfes"], "Ḫalīl nennt sieben Pflichten, darunter Dalk, das Überstreichen des gewaschenen Glieds mit der Hand, und Fawr (Zügigkeit). Dalk ist für Ḥanafiten, Šāfiʿiten und Ḥanbaliten bei der Waschung keine Pflicht."],
    ar: ["أيّ هذه الأفعال فرض في الوضوء عند المالكية دون المذاهب الثلاثة الأخرى؟", ["الدلك", "النية", "غسل الرجلين", "مسح الرأس"], "عدّ خليل الفرائض سبعًا منها الدلك وهو إمرار اليد على العضو، والفور، ولا يجب الدلك في الوضوء عند الحنفية والشافعية والحنابلة."] },

  { id: "fqs-029", s: "fiqh", g: 2, d: 3, t: ["wudu-faraid", "madhhab-comparison"], tr: ["shafii", "comparative"], v: "5:6", w: 14, src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on the amount of the head to be wiped",
    en: ["The schools differ on how much of the head must be wiped, partly over the highlighted word. Which school holds that wiping any small part of the head suffices?", ["Shāfiʿī", "Ḥanafī", "Mālikī", "Ḥanbalī"], "The Shāfiʿīs require only what can be called wiping, even a few hairs within the head. The Ḥanafīs require a quarter, and the Mālikīs and Ḥanbalīs (in their relied-upon views) the whole head."],
    de: ["Die Schulen streiten, wie viel vom Kopf bestrichen werden muss, auch wegen des markierten Wortes. Welche Schule lässt jeden kleinen Teil des Kopfes genügen?", ["Die šāfiʿitische", "Die ḥanafitische", "Die mālikitische", "Die ḥanbalitische"], "Die Šāfiʿiten verlangen nur, was man Bestreichen nennen kann, selbst einige Haare im Kopfbereich. Die Ḥanafiten verlangen ein Viertel, Mālikiten und Ḥanbaliten (nach ihrer maßgeblichen Ansicht) den ganzen Kopf."],
    ar: ["اختلف المذاهب في القدر الواجب من مسح الرأس، ومن أسباب ذلك الكلمة المظللة. أيّ مذهب يكتفي بمسح أدنى جزء من الرأس؟", ["الشافعية", "الحنفية", "المالكية", "الحنابلة"], "يكفي عند الشافعية ما ينطلق عليه اسم المسح ولو بعض شعرة في حد الرأس، والواجب عند الحنفية الربع، وعند المالكية والحنابلة في المعتمد مسح جميع الرأس."] },

  { id: "fqs-030", s: "fiqh", g: 2, d: 2, t: ["wudu-faraid", "niyyah", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ṭahārāt, sunan al-wuḍūʾ",
    en: ["Which school holds that intention (niyya) is a sunna of wuḍūʾ and not a condition of its validity?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "The Ḥanafīs regard water as purifying by its nature, so wuḍūʾ without intention lifts the ḥadath, though without reward. The other three schools make intention obligatory for wuḍūʾ."],
    de: ["Welche Schule hält die Absicht (nīya) für eine Sunna der Waschung und nicht für eine Bedingung ihrer Gültigkeit?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Für die Ḥanafiten reinigt Wasser seiner Natur nach; eine Waschung ohne Absicht hebt die Unreinheit auf, bringt aber keinen Lohn. Die anderen drei Schulen machen die Absicht zur Pflicht."],
    ar: ["أيّ مذهب يجعل النية في الوضوء سنة لا شرطًا لصحته؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "الماء عند الحنفية مطهّر بطبعه، فالوضوء بلا نية يرفع الحدث وإن لم يُثَب عليه، وأوجب الثلاثة النية في الوضوء."] },

  { id: "fqs-031", s: "fiqh", g: 2, d: 2, t: ["wudu-faraid", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on order in wuḍūʾ",
    en: ["Which pair of schools holds that keeping the order of the limbs (tartīb) is obligatory in wuḍūʾ?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs make tartīb a farḍ, following the order of the verse. For the Ḥanafīs and in the well-known Mālikī view it is a sunna."],
    de: ["Welche beiden Schulen halten die Reihenfolge der Glieder (tartīb) bei der Waschung für Pflicht?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten machen den Tartīb nach der Reihenfolge des Verses zur Pflicht. Bei den Ḥanafiten und nach der bekannten mālikitischen Ansicht ist er Sunna."],
    ar: ["أيّ مذهبين يوجبان الترتيب في الوضوء؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "أوجب الشافعية والحنابلة الترتيب على نسق الآية، وهو عند الحنفية والمشهور عند المالكية سنة."] },

  { id: "fqs-032", s: "fiqh", g: 2, d: 2, t: ["wudu-nullifiers", "madhhab-comparison"], tr: ["shafii", "comparative"], v: "4:43", w: 33, src: "al-Nawawī, Minhāj al-Ṭālibīn, bāb asbāb al-ḥadath",
    en: ["The highlighted word is central to a disagreement. Which school holds that skin contact between an adult man and a non-maḥram woman breaks wuḍūʾ even without desire?", ["Shāfiʿī", "Ḥanafī", "Mālikī", "Ḥanbalī"], "The Shāfiʿīs read the 'touching' in the verse literally, so direct skin contact breaks wuḍūʾ. The Ḥanafīs understand it as intercourse; the Mālikīs and Ḥanbalīs (relied-upon view) make it break wuḍūʾ only with desire."],
    de: ["Das markierte Wort steht im Zentrum eines Meinungsstreits. Welche Schule hält, dass Hautkontakt zwischen einem erwachsenen Mann und einer nicht-maḥram Frau die Waschung auch ohne Begierde bricht?", ["Die šāfiʿitische", "Die ḥanafitische", "Die mālikitische", "Die ḥanbalitische"], "Die Šāfiʿiten verstehen die „Berührung“ im Vers wörtlich, also bricht direkter Hautkontakt die Waschung. Die Ḥanafiten deuten sie als Beischlaf; Mālikiten und Ḥanbaliten (maßgebliche Ansicht) nur bei Begierde."],
    ar: ["الكلمة المظللة محلّ خلاف. أيّ مذهب يرى أن التقاء بشرة الرجل بالمرأة الأجنبية ينقض الوضوء ولو بلا شهوة؟", ["الشافعية", "الحنفية", "المالكية", "الحنابلة"], "حمل الشافعية الملامسة على حقيقتها فينقض التقاء البشرتين مطلقًا، وحملها الحنفية على الجماع، وقيّد المالكية والحنابلة في المعتمد النقض بالشهوة."] },

  { id: "fqs-033", s: "fiqh", g: 2, d: 3, t: ["wudu-nullifiers", "madhhab-comparison"], tr: ["maliki", "shafii", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on what exits from other than the two passages",
    en: ["Which pair of schools holds that blood flowing from a wound does not break wuḍūʾ, whatever its amount?", ["Mālikī and Shāfiʿī", "Ḥanafī and Ḥanbalī", "Ḥanafī and Mālikī", "Shāfiʿī and Ḥanbalī"], "For the Mālikīs and Shāfiʿīs, only what exits from the two passages (and a few named causes) breaks wuḍūʾ. The Ḥanafīs count flowing blood as a nullifier, and the Ḥanbalīs a large, offensive amount."],
    de: ["Welche beiden Schulen halten, dass aus einer Wunde fließendes Blut die Waschung unabhängig von der Menge nicht bricht?", ["Mālikiten und Šāfiʿiten", "Ḥanafiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Šāfiʿiten und Ḥanbaliten"], "Für Mālikiten und Šāfiʿiten bricht nur, was aus den beiden Ausgängen kommt (und einige benannte Ursachen). Die Ḥanafiten zählen fließendes Blut zu den Brechern, die Ḥanbaliten eine große, abstoßende Menge."],
    ar: ["أيّ مذهبين يريان أن الدم الخارج من جرح لا ينقض الوضوء قلّ أو كثر؟", ["المالكية والشافعية", "الحنفية والحنابلة", "الحنفية والمالكية", "الشافعية والحنابلة"], "النقض عند المالكية والشافعية بالخارج من السبيلين وأسباب معدودة، وينقض الدم السائل عند الحنفية، والكثير الفاحش عند الحنابلة."] },

  { id: "fqs-034", s: "fiqh", g: 2, d: 3, t: ["wudu-nullifiers", "madhhab-comparison"], tr: ["hanbali", "comparative"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṭahāra, on eating camel meat",
    en: ["Which school holds that eating camel meat breaks wuḍūʾ?", ["Ḥanbalī", "Ḥanafī", "Mālikī", "Shāfiʿī"], "The Ḥanbalīs act on the hadith of Jābir ibn Samura in Ṣaḥīḥ Muslim ordering wuḍūʾ after camel meat. The other three schools understand it as abrogated or as recommendation."],
    de: ["Welche Schule hält, dass der Verzehr von Kamelfleisch die Waschung bricht?", ["Die ḥanbalitische", "Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische"], "Die Ḥanbaliten folgen dem Hadith von Ǧābir ibn Samura in Ṣaḥīḥ Muslim, der nach Kamelfleisch die Waschung anordnet. Die anderen drei Schulen sehen ihn als aufgehoben oder als Empfehlung."],
    ar: ["أيّ مذهب يرى أن أكل لحم الإبل ينقض الوضوء؟", ["الحنابلة", "الحنفية", "المالكية", "الشافعية"], "أخذ الحنابلة بحديث جابر بن سمرة عند مسلم في الأمر بالوضوء من لحوم الإبل، وحمله الثلاثة على النسخ أو الاستحباب."] },

  { id: "fqs-035", s: "fiqh", g: 2, d: 2, t: ["ghusl"], tr: ["jumhur"], src: "Muslim, Ṣaḥīḥ, Kitāb al-Ḥayḍ, on ghusl when the two circumcised parts meet",
    en: ["According to the four schools, does intercourse without ejaculation require ghusl?", ["Yes, penetration alone obliges ghusl", "No, only ejaculation obliges ghusl", "Only wuḍūʾ is required", "Only if it happens at night"], "The hadith that ghusl is due when the two circumcised parts meet, even without emission, is acted upon by the four schools. The early view 'water only from water' is held to be abrogated."],
    de: ["Verlangt Geschlechtsverkehr ohne Samenerguss nach den vier Schulen einen Ġusl?", ["Ja, das Eindringen allein verpflichtet dazu", "Nein, nur der Samenerguss verpflichtet dazu", "Es genügt die Gebetswaschung", "Nur wenn es nachts geschieht"], "Der Hadith, dass Ġusl fällig wird, wenn sich die beiden beschnittenen Teile treffen, auch ohne Erguss, wird von den vier Schulen angewandt. Die frühe Regel „Wasser nur aus Wasser“ gilt als aufgehoben."],
    ar: ["هل يجب الغسل بالجماع من غير إنزال عند المذاهب الأربعة؟", ["نعم، يجب بمجرد التقاء الختانين", "لا، لا يجب إلا بالإنزال", "يكفي الوضوء", "يجب إن كان ليلًا فقط"], "عملت المذاهب الأربعة بحديث وجوب الغسل إذا التقى الختانان وإن لم ينزل، وعدّوا حديث الماء من الماء منسوخًا."] },

  { id: "fqs-036", s: "fiqh", g: 2, d: 2, t: ["najasa", "wudu-nullifiers"], tr: ["jumhur"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ghusl, hadith of ʿAlī on madhy",
    en: ["What does the emission of madhy (pre-seminal fluid) require?", ["Wuḍūʾ and washing the area, not ghusl", "Ghusl, like the emission of semen", "Nothing at all, since it is pure", "Tayammum only"], "In the hadith of ʿAlī the Prophet ﷺ ordered washing the private part and performing wuḍūʾ for madhy. It is impure and breaks wuḍūʾ, but does not oblige ghusl."],
    de: ["Was erfordert der Austritt von Maḏy (Vorsekret)?", ["Waschung und Reinigen der Stelle, kein Ġusl", "Ġusl wie beim Samenerguss", "Nichts, da es rein ist", "Nur Tayammum"], "Im Hadith von ʿAlī ordnete der Prophet ﷺ für Maḏy das Waschen der Scham und die Gebetswaschung an. Es ist unrein und bricht die Waschung, verpflichtet aber nicht zum Ġusl."],
    ar: ["ما الذي يجب بخروج المذي؟", ["غسل الذكر والوضوء دون الغسل", "الغسل كخروج المني", "لا شيء لأنه طاهر", "التيمم فقط"], "في حديث علي أمر النبي ﷺ من المذي بغسل الذكر والوضوء، فهو نجس ناقض للوضوء ولا يوجب الغسل."] },

  { id: "fqs-037", s: "fiqh", g: 2, d: 3, t: ["tayammum", "madhhab-comparison"], tr: ["hanafi", "shafii", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Tayammum, on the limbs and the strikes",
    en: ["Which pair of schools holds that tayammum obligatorily needs two strikes, with the arms wiped up to the elbows?", ["Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī", "Ḥanafī and Ḥanbalī", "Mālikī and Shāfiʿī"], "The Ḥanafīs and Shāfiʿīs require one strike for the face and one for the arms to the elbows. The Ḥanbalīs hold one strike for face and hands to the wrists; the Mālikīs make the wrists obligatory and the elbows and second strike sunna."],
    de: ["Welche beiden Schulen verlangen beim Tayammum verpflichtend zwei Schläge und das Bestreichen der Arme bis zu den Ellbogen?", ["Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten", "Ḥanafiten und Ḥanbaliten", "Mālikiten und Šāfiʿiten"], "Ḥanafiten und Šāfiʿiten verlangen einen Schlag für das Gesicht und einen für die Arme bis zu den Ellbogen. Die Ḥanbaliten genügen mit einem Schlag für Gesicht und Hände bis zum Handgelenk; die Mālikiten machen das Handgelenk zur Pflicht, Ellbogen und zweiten Schlag zur Sunna."],
    ar: ["أيّ مذهبين يوجبان في التيمم ضربتين ومسح اليدين إلى المرفقين؟", ["الحنفية والشافعية", "المالكية والحنابلة", "الحنفية والحنابلة", "المالكية والشافعية"], "أوجب الحنفية والشافعية ضربة للوجه وضربة لليدين إلى المرفقين، واكتفى الحنابلة بضربة واحدة للوجه والكفين، وجعل المالكية الفرض إلى الكوعين والضربة الثانية والمرفقين سنة."] },

  { id: "fqs-038", s: "fiqh", g: 2, d: 3, t: ["najasa", "madhhab-comparison"], tr: ["hanafi"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ṭahārāt, bāb al-anjās wa-taṭhīrihā",
    en: ["Into which two main classes does Ḥanafī fiqh divide najāsa for the amount that is excused?", ["Heavy (mughallaẓa) and light (mukhaffafa)", "Visible and invisible only", "Liquid and solid only", "Human and animal only"], "The Ḥanafīs divide najāsa into mughallaẓa, excused up to the size of a dirham, and mukhaffafa, excused if less than a quarter of the garment or limb. Visible and invisible matter for how it is washed, not for this classification."],
    de: ["In welche zwei Hauptklassen teilt das ḥanafitische Recht die Unreinheit für das entschuldigte Maß ein?", ["Schwer (muġallaẓa) und leicht (muḫaffafa)", "Nur sichtbar und unsichtbar", "Nur flüssig und fest", "Nur menschlich und tierisch"], "Die Ḥanafiten teilen in Muġallaẓa, entschuldigt bis zur Größe eines Dirhams, und Muḫaffafa, entschuldigt unter einem Viertel des Kleidungsstücks oder Glieds. Sichtbar und unsichtbar betrifft die Art des Waschens, nicht diese Einteilung."],
    ar: ["إلى أيّ قسمين رئيسين يقسم الحنفية النجاسة من حيث القدر المعفو عنه؟", ["مغلظة ومخففة", "مرئية وغير مرئية فقط", "مائعة وجامدة فقط", "آدمية وحيوانية فقط"], "يقسم الحنفية النجاسة إلى مغلظة يُعفى منها عن قدر الدرهم، ومخففة يُعفى عمّا دون ربع الثوب أو العضو، أما المرئية وغيرها فتتعلق بكيفية الغسل."] },

  // ---------- Stage 2: ṣalāh ----------
  { id: "fqs-039", s: "fiqh", g: 2, d: 2, t: ["adhan-iqama"], src: "Abū Dāwūd, Sunan, Kitāb al-Ṣalāt, bāb kayfa al-adhān",
    en: ["Which Companion saw the words of the adhān in a dream, which the Prophet ﷺ then approved?", ["ʿAbd Allāh ibn Zayd", "Bilāl ibn Rabāḥ", "Abū Maḥdhūra", "Muʿādh ibn Jabal"], "ʿAbd Allāh ibn Zayd ibn ʿAbd Rabbih saw the adhān in a dream; the Prophet ﷺ called it a true vision and had him teach it to Bilāl, who had the stronger voice. ʿUmar reported a similar dream."],
    de: ["Welcher Gefährte sah die Worte des Adhān im Traum, die der Prophet ﷺ dann bestätigte?", ["ʿAbdallāh ibn Zaid", "Bilāl ibn Rabāḥ", "Abū Maḥḏūra", "Muʿāḏ ibn Ǧabal"], "ʿAbdallāh ibn Zaid ibn ʿAbd Rabbih sah den Adhān im Traum; der Prophet ﷺ nannte ihn eine wahre Schau und ließ ihn Bilāl lehren, der die kräftigere Stimme hatte. ʿUmar berichtete einen ähnlichen Traum."],
    ar: ["مَن الصحابي الذي رأى الأذان في المنام فأقرّه النبي ﷺ؟", ["عبد الله بن زيد", "بلال بن رباح", "أبو محذورة", "معاذ بن جبل"], "رأى عبد الله بن زيد بن عبد ربه الأذان في المنام، فقال النبي ﷺ إنها رؤيا حق وأمره أن يلقيه على بلال لأنه أندى صوتًا، ورأى عمر مثل ذلك."] },

  { id: "fqs-040", s: "fiqh", g: 2, d: 3, t: ["prayer-times", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ṣalāt, bāb al-mawāqīt",
    en: ["According to the view of Abū Ḥanīfa, when does the time of ʿAṣr begin?", ["When an object's shadow becomes twice its length", "When the shadow equals the object's length", "Immediately after the sun's zenith", "When the sun turns yellow"], "Abū Ḥanīfa held that Ẓuhr lasts until the shadow is twice the object (besides the zenith shadow). The majority, including his two companions, start ʿAṣr when the shadow equals the object."],
    de: ["Wann beginnt nach der Ansicht von Abū Ḥanīfa die Zeit des ʿAṣr?", ["Wenn der Schatten doppelt so lang ist wie der Gegenstand", "Wenn der Schatten so lang ist wie der Gegenstand", "Unmittelbar nach dem Zenit", "Wenn die Sonne gelb wird"], "Abū Ḥanīfa hielt, dass Ẓuhr dauert, bis der Schatten doppelt so lang ist wie der Gegenstand (zusätzlich zum Mittagsschatten). Die Mehrheit, auch seine beiden Schüler, lässt ʿAṣr beim einfachen Schatten beginnen."],
    ar: ["متى يدخل وقت العصر على قول أبي حنيفة؟", ["إذا صار ظل الشيء مثليه", "إذا صار ظل الشيء مثله", "بعد الزوال مباشرة", "عند اصفرار الشمس"], "يرى أبو حنيفة أن الظهر يمتد حتى يصير ظل الشيء مثليه سوى فيء الزوال، وعند الجمهور ومنهم صاحباه يدخل العصر بمصير الظل مثله."] },

  { id: "fqs-041", s: "fiqh", g: 2, d: 2, t: ["prayer-times", "nafl-prayer"], tr: ["jumhur"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Mawāqīt al-Ṣalāt, on not praying after ʿAṣr",
    en: ["Which of these is a time in which voluntary prayer without a particular cause is prohibited according to the four schools?", ["After the ʿAṣr prayer until sunset", "After Maghrib until ʿIshāʾ", "After ʿIshāʾ until midnight", "After Ẓuhr until ʿAṣr"], "The hadith forbids prayer after ʿAṣr until sunset and after Fajr until sunrise, as well as at sunrise, zenith and sunset. The schools differ about prayers that have a cause, but not about this basic time."],
    de: ["In welcher Zeit ist ein freiwilliges Gebet ohne besonderen Anlass nach den vier Schulen untersagt?", ["Nach dem ʿAṣr-Gebet bis Sonnenuntergang", "Nach Maġrib bis ʿIšāʾ", "Nach ʿIšāʾ bis Mitternacht", "Nach Ẓuhr bis ʿAṣr"], "Der Hadith verbietet das Gebet nach ʿAṣr bis Sonnenuntergang und nach Faǧr bis Sonnenaufgang sowie bei Aufgang, Zenit und Untergang. Die Schulen streiten über Gebete mit Anlass, nicht über diese Grundzeit."],
    ar: ["أيّ هذه أوقات يُنهى فيها عن النافلة المطلقة عند المذاهب الأربعة؟", ["بعد صلاة العصر حتى الغروب", "بعد المغرب حتى العشاء", "بعد العشاء حتى منتصف الليل", "بعد الظهر حتى العصر"], "نهى الحديث عن الصلاة بعد العصر حتى تغرب الشمس وبعد الفجر حتى تطلع، وعند الطلوع والاستواء والغروب، والخلاف في ذوات الأسباب لا في أصل الوقت."] },

  { id: "fqs-042", s: "fiqh", g: 2, d: 3, t: ["witr", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ṣalāt, bāb ṣalāt al-witr",
    en: ["Who held that the witr prayer is wājib, a level between farḍ and sunna?", ["Abū Ḥanīfa", "Mālik", "al-Shāfiʿī", "Aḥmad ibn Ḥanbal"], "Abū Ḥanīfa considered witr wājib; his two companions and the other three schools hold it to be an emphasised sunna. This is why Ḥanafī texts treat missing it more severely."],
    de: ["Wer hielt das Witr-Gebet für wāǧib, eine Stufe zwischen farḍ und Sunna?", ["Abū Ḥanīfa", "Mālik", "aš-Šāfiʿī", "Aḥmad ibn Ḥanbal"], "Abū Ḥanīfa hielt Witr für wāǧib; seine beiden Schüler und die anderen drei Schulen halten es für eine bekräftigte Sunna. Deshalb behandeln ḥanafitische Texte sein Auslassen strenger."],
    ar: ["مَن قال بوجوب الوتر وجوبًا دون الفرض وفوق السنة؟", ["أبو حنيفة", "مالك", "الشافعي", "أحمد بن حنبل"], "الوتر واجب عند أبي حنيفة، وسنة مؤكدة عند صاحبيه والمذاهب الثلاثة."] },

  { id: "fqs-043", s: "fiqh", g: 2, d: 3, t: ["qasr-jam", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Qudūrī, al-Mukhtaṣar, bāb ṣalāt al-musāfir",
    en: ["Which school holds that shortening the four-rakʿa prayers on a journey is obligatory, not merely permitted?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "For the Ḥanafīs the traveller's prayer is two rakʿas as its original form ('azīma). The Mālikīs call qaṣr an emphasised sunna, and the Shāfiʿīs and Ḥanbalīs a concession that may be left."],
    de: ["Welche Schule hält das Verkürzen der Vier-Rakʿa-Gebete auf Reisen für Pflicht und nicht nur für erlaubt?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Für die Ḥanafiten ist das Reisegebet in seiner ursprünglichen Form zwei Rakʿas (ʿazīma). Die Mālikiten nennen Qaṣr eine bekräftigte Sunna, Šāfiʿiten und Ḥanbaliten eine Erleichterung, die man lassen darf."],
    ar: ["أيّ مذهب يرى قصر الرباعية في السفر واجبًا لا مجرد رخصة؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "صلاة المسافر عند الحنفية ركعتان عزيمة، والقصر عند المالكية سنة مؤكدة، وعند الشافعية والحنابلة رخصة يجوز تركها."] },

  { id: "fqs-044", s: "fiqh", g: 2, d: 3, t: ["qasr-jam", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb ṣalāt al-musāfir",
    en: ["According to the Ḥanafī school, when may two prayers be combined in one time (jamʿ)?", ["Only at ʿArafa and Muzdalifa during Ḥajj", "On any journey of the shortening distance", "Whenever there is heavy rain", "For illness and for any need"], "The Ḥanafīs allow real combining only at ʿArafa (Ẓuhr and ʿAṣr) and Muzdalifa (Maghrib and ʿIshāʾ). Other reports of combining they read as apparent combining: the first prayer at the end of its time and the second at the start of its own."],
    de: ["Wann dürfen nach der ḥanafitischen Schule zwei Gebete zusammengelegt werden (ǧamʿ)?", ["Nur in ʿArafa und Muzdalifa während der Ḥaǧǧ", "Auf jeder Reise der Verkürzungsdistanz", "Bei jedem starken Regen", "Bei Krankheit und jedem Bedarf"], "Die Ḥanafiten erlauben echtes Zusammenlegen nur in ʿArafa (Ẓuhr und ʿAṣr) und Muzdalifa (Maġrib und ʿIšāʾ). Andere Berichte deuten sie als scheinbares Zusammenlegen: das erste Gebet am Ende seiner Zeit, das zweite am Anfang der eigenen."],
    ar: ["متى يجوز الجمع بين الصلاتين عند الحنفية؟", ["بعرفة ومزدلفة في الحج فقط", "في كل سفر قصر", "عند كل مطر شديد", "للمرض ولكل حاجة"], "لا يجيز الحنفية الجمع الحقيقي إلا بعرفة بين الظهر والعصر وبمزدلفة بين المغرب والعشاء، ويحملون ما ورد من الجمع على الجمع الصوري."] },

  { id: "fqs-045", s: "fiqh", g: 2, d: 3, t: ["sujud-sahw", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Qudūrī, al-Mukhtaṣar, bāb sujūd al-sahw",
    en: ["In the Ḥanafī school, where are the prostrations of forgetfulness (sujūd al-sahw) performed?", ["After one salām, then tashahhud and salām again", "Always before the final salām", "Before salām for omissions, after for additions", "After the prayer is fully ended and one has stood up"], "The Ḥanafīs give one salām to the right, make two prostrations, then repeat the tashahhud and close with salām. The Shāfiʿīs place them before salām, and the Mālikīs distinguish omission and addition."],
    de: ["Wo werden in der ḥanafitischen Schule die Niederwerfungen des Vergessens (suǧūd as-sahw) verrichtet?", ["Nach einem Salām, dann Tašahhud und erneut Salām", "Immer vor dem abschließenden Salām", "Vor dem Salām bei Auslassung, danach bei Hinzufügung", "Nach dem vollständigen Ende des Gebets im Aufstehen"], "Die Ḥanafiten sprechen einen Salām nach rechts, werfen sich zweimal nieder, wiederholen den Tašahhud und schließen mit dem Salām. Die Šāfiʿiten legen sie vor den Salām, die Mālikiten unterscheiden Auslassung und Hinzufügung."],
    ar: ["أين يكون سجود السهو عند الحنفية؟", ["بعد تسليمة واحدة ثم يتشهد ويسلم", "قبل السلام دائمًا", "قبل السلام للنقص وبعده للزيادة", "بعد انتهاء الصلاة والقيام منها"], "يسلم الحنفية تسليمة عن اليمين ثم يسجدون سجدتين ثم يتشهدون ويسلمون، وهو عند الشافعية قبل السلام، وفرّق المالكية بين النقص والزيادة."] },

  { id: "fqs-046", s: "fiqh", g: 2, d: 3, t: ["sujud-sahw"], tr: ["jumhur"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Sahw, hadith of ʿAbd Allāh ibn Buḥayna",
    en: ["A person forgets the first tashahhud and has already stood up fully for the third rakʿa. What do the schools generally hold?", ["He continues and prostrates for forgetfulness", "He must sit back down for the tashahhud", "His prayer is void and must be restarted", "He continues and owes nothing"], "In the hadith of Ibn Buḥayna the Prophet ﷺ stood up after two rakʿas, did not return, and prostrated for forgetfulness before the salām. The schools hold that one who has fully stood does not go back; the Ḥanbalīs call returning disliked, the Shāfiʿīs forbidden."],
    de: ["Jemand vergisst den ersten Tašahhud und steht bereits vollständig zur dritten Rakʿa. Was halten die Schulen im Allgemeinen?", ["Er setzt fort und wirft sich für das Vergessen nieder", "Er muss sich zum Tašahhud wieder setzen", "Sein Gebet ist ungültig und neu zu beginnen", "Er setzt fort und schuldet nichts"], "Im Hadith von Ibn Buḥaina stand der Prophet ﷺ nach zwei Rakʿas auf, kehrte nicht zurück und warf sich vor dem Salām für das Vergessen nieder. Wer ganz aufgestanden ist, kehrt nach den Schulen nicht zurück; die Ḥanbaliten nennen die Rückkehr verpönt, die Šāfiʿiten verboten."],
    ar: ["نسي المصلي التشهد الأول واستتم قائمًا للثالثة، فماذا يرى عامة المذاهب؟", ["يمضي ويسجد للسهو", "يجب أن يرجع فيجلس للتشهد", "تبطل صلاته فيستأنفها", "يمضي ولا شيء عليه"], "في حديث ابن بحينة قام النبي ﷺ من اثنتين فلم يرجع وسجد للسهو قبل السلام، فمن استتم قائمًا لا يرجع، ويكره الحنابلة الرجوع ويحرّمه الشافعية."] },

  { id: "fqs-047", s: "fiqh", g: 2, d: 2, t: ["congregation", "masbuq"], tr: ["jumhur"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣalāt, on catching the rakʿa",
    en: ["A latecomer joins the imam while he is still in rukūʿ and settles in it with him. According to the four schools, what is the result?", ["He has caught that rakʿa", "He must repeat that rakʿa at the end", "He has caught only the sujūd", "His prayer is void"], "The four schools hold that whoever catches the rukūʿ with the imam has caught the rakʿa, even though he missed the recitation. He makes the opening takbīr standing, then goes into rukūʿ."],
    de: ["Ein Nachzügler schließt sich dem Imam an, während dieser noch in der Verbeugung ist, und kommt darin mit ihm zur Ruhe. Was folgt nach den vier Schulen?", ["Er hat diese Rakʿa erreicht", "Er muss diese Rakʿa am Ende wiederholen", "Er hat nur die Niederwerfung erreicht", "Sein Gebet ist ungültig"], "Nach den vier Schulen hat, wer die Verbeugung mit dem Imam erreicht, die Rakʿa erreicht, auch wenn er die Rezitation verpasst hat. Er spricht den Eröffnungs-Takbīr stehend und geht dann in die Verbeugung."],
    ar: ["أدرك المسبوق الإمام راكعًا واطمأن معه في الركوع، فما الحكم عند المذاهب الأربعة؟", ["أدرك الركعة", "يقضي تلك الركعة في آخر صلاته", "أدرك السجود فقط", "بطلت صلاته"], "من أدرك الركوع مع الإمام فقد أدرك الركعة عند المذاهب الأربعة وإن فاتته القراءة، فيكبر للإحرام قائمًا ثم يركع."] },

  { id: "fqs-048", s: "fiqh", g: 2, d: 2, t: ["nafl-prayer"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Tahajjud, hadith of ʿĀʾisha on the two rakʿas of Fajr",
    en: ["According to ʿĀʾisha, which voluntary prayer did the Prophet ﷺ keep up more consistently than any other?", ["The two rakʿas before Fajr", "The four rakʿas before Ẓuhr", "The two rakʿas after Maghrib", "The prayer of ḍuḥā"], "ʿĀʾisha reported that the Prophet ﷺ was not more regular in any voluntary prayer than the two rakʿas before Fajr. He kept them even on journeys."],
    de: ["Welches freiwillige Gebet hielt der Prophet ﷺ nach ʿĀʾiša beständiger ein als jedes andere?", ["Die zwei Rakʿas vor Faǧr", "Die vier Rakʿas vor Ẓuhr", "Die zwei Rakʿas nach Maġrib", "Das Ḍuḥā-Gebet"], "ʿĀʾiša berichtete, dass der Prophet ﷺ kein freiwilliges Gebet so regelmäßig verrichtete wie die zwei Rakʿas vor Faǧr. Er hielt sie sogar auf Reisen ein."],
    ar: ["أيّ النوافل كان النبي ﷺ أشدّ تعاهدًا لها بحسب حديث عائشة؟", ["ركعتا الفجر", "أربع قبل الظهر", "ركعتان بعد المغرب", "صلاة الضحى"], "أخبرت عائشة أن النبي ﷺ لم يكن على شيء من النوافل أشد تعاهدًا منه على ركعتي الفجر، وكان لا يدعهما سفرًا ولا حضرًا."] },

  { id: "fqs-049", s: "fiqh", g: 2, d: 3, t: ["salah-wajibat", "sujud-sahw"], tr: ["hanafi"], src: "al-Marghīnānī, al-Hidāya, bāb sujūd al-sahw",
    en: ["In Ḥanafī fiqh, what is the consequence of leaving a wājib of the prayer by mistake?", ["It is made good by sujūd al-sahw", "The prayer is void and must be repeated", "Nothing, since wājib acts are only recommended", "The rakʿa must be repeated at once"], "For the Ḥanafīs, a wājib left by oversight is compensated with the prostrations of forgetfulness. Leaving a farḍ voids the prayer; leaving a wājib deliberately makes repeating the prayer necessary."],
    de: ["Welche Folge hat im ḥanafitischen Recht das versehentliche Auslassen eines Wāǧib des Gebets?", ["Es wird durch Suǧūd as-Sahw ausgeglichen", "Das Gebet ist ungültig und zu wiederholen", "Nichts, da Wāǧib nur empfohlen ist", "Die Rakʿa ist sofort zu wiederholen"], "Für die Ḥanafiten wird ein versehentlich ausgelassenes Wāǧib durch die Niederwerfungen des Vergessens ausgeglichen. Das Auslassen eines Farḍ macht das Gebet ungültig; das bewusste Auslassen eines Wāǧib macht die Wiederholung nötig."],
    ar: ["ما حكم ترك واجب من واجبات الصلاة سهوًا عند الحنفية؟", ["يُجبر بسجود السهو", "تبطل الصلاة وتجب إعادتها", "لا شيء لأن الواجب مستحب", "يعيد الركعة في الحال"], "الواجب المتروك سهوًا عند الحنفية يُجبر بسجود السهو، وترك الفرض يبطل الصلاة، وترك الواجب عمدًا يوجب الإعادة."] },

  { id: "fqs-050", s: "fiqh", g: 2, d: 2, t: ["fiqh-texts"], tr: ["hanafi"], src: "Ibn Quṭlūbughā, Tāj al-Tarājim, entry on al-Qudūrī",
    en: ["al-Mukhtaṣar of al-Qudūrī, a classic primer covering ṭahāra and ṣalāh, belongs to which school?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "Abū al-Ḥusayn al-Qudūrī (d. 428 AH) wrote the Mukhtaṣar, which al-Marghīnānī later combined with al-Jāmiʿ al-Ṣaghīr in Bidāyat al-Mubtadī, the base of al-Hidāya."],
    de: ["Zu welcher Schule gehört al-Muḫtaṣar von al-Qudūrī, ein klassisches Grundlagenwerk zu Ṭahāra und Ṣalāh?", ["Zur ḥanafitischen", "Zur mālikitischen", "Zur šāfiʿitischen", "Zur ḥanbalitischen"], "Abū l-Ḥusain al-Qudūrī (gest. 428 n. H.) verfasste den Muḫtaṣar, den al-Marġīnānī später mit al-Ǧāmiʿ aṣ-Ṣaġīr zu Bidāyat al-Mubtadī verband, der Grundlage der Hidāya."],
    ar: ["إلى أيّ مذهب ينتمي مختصر القدوري، المتن المشهور في الطهارة والصلاة وغيرهما؟", ["الحنفي", "المالكي", "الشافعي", "الحنبلي"], "صنّف أبو الحسين القدوري (ت 428هـ) المختصر، وجمع المرغيناني بينه وبين الجامع الصغير في بداية المبتدي الذي شرحه في الهداية."] },

  { id: "fqs-051", s: "fiqh", g: 2, d: 2, t: ["fiqh-texts"], tr: ["shafii"], src: "al-Nawawī, Minhāj al-Ṭālibīn, introduction",
    en: ["Who wrote Minhāj al-Ṭālibīn, a central text of the Shāfiʿī school?", ["al-Nawawī", "al-Rāfiʿī", "Ibn Ḥajar al-Haytamī", "al-Ghazālī"], "Al-Nawawī wrote the Minhāj as an abridgement of al-Muḥarrar by al-Rāfiʿī. Ibn Ḥajar al-Haytamī later wrote the commentary Tuḥfat al-Muḥtāj on it."],
    de: ["Wer verfasste Minhāǧ aṭ-Ṭālibīn, einen zentralen Text der šāfiʿitischen Schule?", ["an-Nawawī", "ar-Rāfiʿī", "Ibn Ḥaǧar al-Haitamī", "al-Ġazālī"], "An-Nawawī schrieb den Minhāǧ als Kurzfassung von al-Muḥarrar von ar-Rāfiʿī. Ibn Ḥaǧar al-Haitamī verfasste später dazu den Kommentar Tuḥfat al-Muḥtāǧ."],
    ar: ["مَن مؤلف منهاج الطالبين، من أهم متون المذهب الشافعي؟", ["النووي", "الرافعي", "ابن حجر الهيتمي", "الغزالي"], "اختصر النووي المنهاج من المحرَّر للرافعي، وشرحه ابن حجر الهيتمي في تحفة المحتاج."] },

  { id: "fqs-052", s: "fiqh", g: 2, d: 3, t: ["fiqh-texts"], tr: ["maliki"], src: "Ibn Abī Zayd al-Qayrawānī, al-Risāla, introduction",
    en: ["Who wrote al-Risāla, the well-known Mālikī primer that opens with creed and then treats ṭahāra and ṣalāh?", ["Ibn Abī Zayd al-Qayrawānī", "Khalīl ibn Isḥāq", "Ibn ʿAbd al-Barr", "Saḥnūn"], "Ibn Abī Zayd al-Qayrawānī (d. 386 AH) wrote al-Risāla for teaching the young. Khalīl wrote the later Mukhtaṣar, and Saḥnūn compiled al-Mudawwana."],
    de: ["Wer verfasste al-Risāla, das bekannte mālikitische Lehrbuch, das mit der Glaubenslehre beginnt und dann Ṭahāra und Ṣalāh behandelt?", ["Ibn Abī Zaid al-Qairawānī", "Ḫalīl ibn Isḥāq", "Ibn ʿAbd al-Barr", "Saḥnūn"], "Ibn Abī Zaid al-Qairawānī (gest. 386 n. H.) schrieb al-Risāla für den Unterricht der Jugend. Ḫalīl verfasste den späteren Muḫtaṣar, Saḥnūn stellte al-Mudawwana zusammen."],
    ar: ["مَن مؤلف الرسالة، المتن المالكي المشهور الذي يبدأ بالعقيدة ثم الطهارة والصلاة؟", ["ابن أبي زيد القيرواني", "خليل بن إسحاق", "ابن عبد البر", "سحنون"], "ألّف ابن أبي زيد القيرواني (ت 386هـ) الرسالة لتعليم الناشئة، أما خليل فصاحب المختصر المتأخر، وسحنون جامع المدونة."] },

  { id: "fqs-053", s: "fiqh", g: 2, d: 2, t: ["eid"], tr: ["jumhur"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-ʿĪdayn, on the prayer before the sermon",
    en: ["How does the order of prayer and sermon in the ʿĪd prayer differ from Jumuʿa?", ["In ʿĪd the prayer comes first, then the sermon", "In ʿĪd the sermon comes first, as in Jumuʿa", "ʿĪd has a sermon before and after the prayer", "ʿĪd has no sermon at all"], "The Prophet ﷺ, Abū Bakr and ʿUmar prayed the ʿĪd prayer before the sermon. In Jumuʿa the two sermons precede the prayer and are a condition of its validity."],
    de: ["Wie unterscheidet sich die Reihenfolge von Gebet und Predigt beim ʿĪd-Gebet von der Ǧumuʿa?", ["Beim ʿĪd kommt erst das Gebet, dann die Predigt", "Beim ʿĪd kommt zuerst die Predigt wie bei der Ǧumuʿa", "Beim ʿĪd gibt es eine Predigt vor und nach dem Gebet", "Das ʿĪd hat überhaupt keine Predigt"], "Der Prophet ﷺ, Abū Bakr und ʿUmar beteten das ʿĪd-Gebet vor der Predigt. Bei der Ǧumuʿa gehen die beiden Predigten dem Gebet voraus und sind Bedingung seiner Gültigkeit."],
    ar: ["كيف يختلف ترتيب الصلاة والخطبة في العيد عن الجمعة؟", ["في العيد الصلاة أولًا ثم الخطبة", "في العيد الخطبة أولًا كالجمعة", "في العيد خطبة قبل الصلاة وبعدها", "لا خطبة في العيد أصلًا"], "صلّى النبي ﷺ وأبو بكر وعمر العيد قبل الخطبة، أما الجمعة فخطبتاها قبل الصلاة وهما شرط لصحتها."] },

  // ---------- Stage 3: ṭahāra ----------
  { id: "fqs-054", s: "fiqh", g: 3, d: 3, t: ["wudu-faraid", "madhhab-comparison"], tr: ["hanbali", "hanafi", "comparative"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṭahāra, on rinsing the mouth and nose",
    en: ["In the Ḥanbalī school, rinsing the mouth and nose is obligatory in wuḍūʾ as part of washing the face. What is its status in Ḥanafī wuḍūʾ?", ["Sunna", "Farḍ", "Wājib", "Makrūh"], "The Ḥanbalīs count the mouth and nose as part of the face, so rinsing them is obligatory in both wuḍūʾ and ghusl. The Ḥanafīs make them sunna in wuḍūʾ but obligatory in ghusl."],
    de: ["Bei den Ḥanbaliten ist Mund- und Nasenspülung als Teil des Gesichtswaschens bei der Waschung Pflicht. Welchen Status hat sie bei der ḥanafitischen Waschung?", ["Sunna", "Farḍ", "Wāǧib", "Makrūh"], "Die Ḥanbaliten zählen Mund und Nase zum Gesicht, daher ist ihre Spülung bei Waschung und Ġusl Pflicht. Die Ḥanafiten machen sie bei der Waschung zur Sunna, beim Ġusl aber zur Pflicht."],
    ar: ["المضمضة والاستنشاق عند الحنابلة واجبان في الوضوء لأنهما من الوجه. فما حكمهما في الوضوء عند الحنفية؟", ["سنة", "فرض", "واجب", "مكروه"], "يعدّ الحنابلة الفم والأنف من الوجه فيوجبون المضمضة والاستنشاق في الوضوء والغسل، وهما عند الحنفية سنتان في الوضوء فرضان في الغسل."] },

  { id: "fqs-055", s: "fiqh", g: 3, d: 3, t: ["wudu-faraid", "madhhab-comparison"], tr: ["maliki", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on continuity in wuḍūʾ",
    en: ["Which pair of schools makes continuity (muwālāt), washing the limbs without a long break, obligatory in wuḍūʾ?", ["Mālikī and Ḥanbalī", "Ḥanafī and Shāfiʿī", "Ḥanafī and Mālikī", "Shāfiʿī and Ḥanbalī"], "The Mālikīs (with remembering and ability) and the Ḥanbalīs make muwālāt a farḍ. The Ḥanafīs and the Shāfiʿīs, in the new view of al-Shāfiʿī, consider it a sunna."],
    de: ["Welche beiden Schulen machen die Zügigkeit (muwālāt), das Waschen der Glieder ohne lange Unterbrechung, zur Pflicht der Waschung?", ["Mālikiten und Ḥanbaliten", "Ḥanafiten und Šāfiʿiten", "Ḥanafiten und Mālikiten", "Šāfiʿiten und Ḥanbaliten"], "Die Mālikiten (bei Erinnerung und Fähigkeit) und die Ḥanbaliten machen die Muwālāt zur Pflicht. Ḥanafiten und Šāfiʿiten, nach der neuen Lehre aš-Šāfiʿīs, halten sie für Sunna."],
    ar: ["أيّ مذهبين يوجبان الموالاة في الوضوء؟", ["المالكية والحنابلة", "الحنفية والشافعية", "الحنفية والمالكية", "الشافعية والحنابلة"], "أوجب المالكية الموالاة مع الذكر والقدرة، وأوجبها الحنابلة، وهي سنة عند الحنفية والشافعية في الجديد."] },

  { id: "fqs-056", s: "fiqh", g: 3, d: 4, t: ["wudu-nullifiers", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, Kitāb al-Ṭahārāt, nawāqiḍ al-wuḍūʾ",
    en: ["Which school holds that loud laughter (qahqaha) of an adult during a prayer with rukūʿ and sujūd breaks wuḍūʾ as well as the prayer?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "The Ḥanafīs act on a report about Companions who laughed in prayer and were ordered to repeat wuḍūʾ and prayer. The other schools hold that laughter voids the prayer but not wuḍūʾ, and the Ḥanafīs do not apply it outside prayer or in the funeral prayer."],
    de: ["Welche Schule hält, dass lautes Lachen (qahqaha) eines Erwachsenen in einem Gebet mit Rukūʿ und Suǧūd sowohl das Gebet als auch die Waschung bricht?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Ḥanafiten folgen einem Bericht über Gefährten, die im Gebet lachten und Waschung und Gebet wiederholen sollten. Die anderen Schulen halten, dass Lachen das Gebet, nicht aber die Waschung ungültig macht; außerhalb des Gebets und im Totengebet wenden die Ḥanafiten es nicht an."],
    ar: ["أيّ مذهب يرى أن القهقهة من البالغ في صلاة ذات ركوع وسجود تنقض الوضوء مع الصلاة؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "أخذ الحنفية بالأثر في أمر من ضحك في الصلاة بإعادة الوضوء والصلاة، وعند الثلاثة تبطل الصلاة لا الوضوء، ولا ينقض عند الحنفية خارج الصلاة ولا في صلاة الجنازة."] },

  { id: "fqs-057", s: "fiqh", g: 3, d: 3, t: ["ghusl", "madhhab-comparison"], tr: ["hanafi", "hanbali", "comparative"], src: "al-Qudūrī, al-Mukhtaṣar, bāb al-ghusl; Ibn Qudāma, ʿUmdat al-Fiqh, bāb al-ghusl",
    en: ["Which pair of schools holds that rinsing the mouth and nose is obligatory in ghusl?", ["Ḥanafī and Ḥanbalī", "Mālikī and Shāfiʿī", "Ḥanafī and Mālikī", "Shāfiʿī and Ḥanbalī"], "For the Ḥanafīs ghusl requires washing everything that can be reached, including mouth and nose; the Ḥanbalīs require them in both purifications. The Mālikīs and Shāfiʿīs make them sunna in ghusl."],
    de: ["Welche beiden Schulen halten Mund- und Nasenspülung beim Ġusl für Pflicht?", ["Ḥanafiten und Ḥanbaliten", "Mālikiten und Šāfiʿiten", "Ḥanafiten und Mālikiten", "Šāfiʿiten und Ḥanbaliten"], "Für die Ḥanafiten verlangt der Ġusl das Waschen alles Erreichbaren, auch von Mund und Nase; die Ḥanbaliten verlangen sie bei beiden Reinigungen. Mālikiten und Šāfiʿiten machen sie beim Ġusl zur Sunna."],
    ar: ["أيّ مذهبين يوجبان المضمضة والاستنشاق في الغسل؟", ["الحنفية والحنابلة", "المالكية والشافعية", "الحنفية والمالكية", "الشافعية والحنابلة"], "يوجب الحنفية في الغسل إيصال الماء إلى كل ما يمكن غسله ومنه الفم والأنف، ويوجبهما الحنابلة في الطهارتين، وهما سنتان في الغسل عند المالكية والشافعية."] },

  { id: "fqs-058", s: "fiqh", g: 3, d: 4, t: ["najasa", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra min al-najas, on semen",
    en: ["Which pair of schools holds that human semen (manī) is pure?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs consider manī pure, citing ʿĀʾisha scraping it off the Prophet's ﷺ garment. The Ḥanafīs and Mālikīs hold it impure; the Ḥanafīs allow rubbing off when dry."],
    de: ["Welche beiden Schulen halten menschlichen Samen (manī) für rein?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten halten Manī für rein und verweisen darauf, dass ʿĀʾiša ihn vom Gewand des Propheten ﷺ abkratzte. Ḥanafiten und Mālikiten halten ihn für unrein; die Ḥanafiten lassen trocken das Abreiben genügen."],
    ar: ["أيّ مذهبين يريان طهارة المني؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "يرى الشافعية والحنابلة طهارة المني لفرك عائشة له من ثوب النبي ﷺ، ويراه الحنفية والمالكية نجسًا، ويكفي فركه يابسًا عند الحنفية."] },

  { id: "fqs-059", s: "fiqh", g: 3, d: 4, t: ["tayammum", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], v: "4:43", w: 39, src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Tayammum, on what tayammum is made with",
    en: ["The schools differ over the meaning of the highlighted word. Which pair holds that tayammum is valid only with dust (turāb) that has powder?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs restrict ṣaʿīd to pure dust with powder that clings. The Ḥanafīs and Mālikīs allow anything of the earth's surface, such as stone or sand."],
    de: ["Die Schulen streiten über die Bedeutung des markierten Wortes. Welche beiden halten Tayammum nur mit staubiger Erde (turāb) für gültig?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten beschränken Ṣaʿīd auf reine Erde mit haftendem Staub. Ḥanafiten und Mālikiten erlauben alles von der Erdoberfläche, etwa Stein oder Sand."],
    ar: ["اختلف المذاهب في معنى الكلمة المظللة. أيّ مذهبين لا يجيزان التيمم إلا بتراب له غبار؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "خصّ الشافعية والحنابلة الصعيد بالتراب الطهور ذي الغبار، وأجاز الحنفية والمالكية التيمم بكل ما كان من جنس الأرض كالحجر والرمل."] },

  { id: "fqs-060", s: "fiqh", g: 3, d: 3, t: ["masah-khuffayn", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Khalīl ibn Isḥāq, al-Mukhtaṣar, faṣl al-masḥ ʿalā al-khuffayn",
    en: ["Which school, in its well-known view, sets no fixed time limit for wiping over the khuffayn?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The well-known Mālikī position allows masḥ without a time limit, while recommending removal once a week, on Friday. The other three schools apply one day and night for the resident and three for the traveller."],
    de: ["Welche Schule setzt nach ihrer bekannten Ansicht keine feste Frist für das Bestreichen der Ḫuffain?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die bekannte mālikitische Position erlaubt Masḥ ohne Frist und empfiehlt, die Ḫuffain einmal wöchentlich am Freitag auszuziehen. Die anderen drei Schulen wenden einen Tag und eine Nacht für Ansässige und drei für Reisende an."],
    ar: ["أيّ مذهب لا يوقّت المسح على الخفين في المشهور؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "المشهور عند المالكية جواز المسح بلا توقيت مع استحباب نزعهما كل جمعة، ووقّت الثلاثة يومًا وليلة للمقيم وثلاثة للمسافر."] },

  { id: "fqs-061", s: "fiqh", g: 3, d: 3, t: ["hayd-nifas", "madhhab-comparison"], tr: ["hanafi"], src: "al-Qudūrī, al-Mukhtaṣar, bāb al-ḥayḍ",
    en: ["According to the Ḥanafī school, what are the minimum and maximum lengths of menstruation?", ["Three days and ten days", "One day and night and fifteen days", "No minimum and fifteen days", "One day and seven days"], "The Ḥanafīs set three days as the minimum and ten as the maximum. The Shāfiʿīs and Ḥanbalīs hold a day and night and fifteen days; the Mālikīs have no minimum for worship and fifteen days as maximum."],
    de: ["Was sind nach der ḥanafitischen Schule die Mindest- und Höchstdauer der Menstruation?", ["Drei Tage und zehn Tage", "Ein Tag und eine Nacht und fünfzehn Tage", "Kein Minimum und fünfzehn Tage", "Ein Tag und sieben Tage"], "Die Ḥanafiten setzen drei Tage als Minimum und zehn als Maximum. Šāfiʿiten und Ḥanbaliten nennen einen Tag und eine Nacht und fünfzehn Tage; die Mālikiten kennen für die Gottesdienste kein Minimum und fünfzehn Tage als Maximum."],
    ar: ["ما أقل الحيض وأكثره عند الحنفية؟", ["ثلاثة أيام وعشرة أيام", "يوم وليلة وخمسة عشر يومًا", "لا حدّ لأقله وخمسة عشر يومًا", "يوم واحد وسبعة أيام"], "أقل الحيض عند الحنفية ثلاثة أيام وأكثره عشرة، وعند الشافعية والحنابلة يوم وليلة وخمسة عشر، ولا حدّ لأقله في العبادات عند المالكية وأكثره خمسة عشر."] },

  { id: "fqs-062", s: "fiqh", g: 3, d: 4, t: ["hayd-nifas", "madhhab-comparison"], tr: ["shafii", "maliki", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ḥayḍ, on the length of nifās",
    en: ["Which pair of schools gives sixty days as the maximum length of post-natal bleeding (nifās)?", ["Shāfiʿī and Mālikī", "Ḥanafī and Ḥanbalī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Mālikīs set sixty days as the maximum. The Ḥanafīs and Ḥanbalīs set forty, following the report of Umm Salama."],
    de: ["Welche beiden Schulen nennen sechzig Tage als Höchstdauer der Wochenbettblutung (nifās)?", ["Šāfiʿiten und Mālikiten", "Ḥanafiten und Ḥanbaliten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Mālikiten setzen sechzig Tage als Maximum. Ḥanafiten und Ḥanbaliten setzen vierzig nach dem Bericht von Umm Salama."],
    ar: ["أيّ مذهبين يجعلان أكثر النفاس ستين يومًا؟", ["الشافعية والمالكية", "الحنفية والحنابلة", "الحنفية والشافعية", "المالكية والحنابلة"], "أكثر النفاس ستون يومًا عند الشافعية والمالكية، وأربعون عند الحنفية والحنابلة لحديث أم سلمة."] },

  { id: "fqs-063", s: "fiqh", g: 3, d: 4, t: ["najasa", "madhhab-comparison"], tr: ["shafii"], src: "al-Nawawī, Minhāj al-Ṭālibīn, bāb al-najāsa",
    en: ["In the Shāfiʿī school, which najāsa is 'light' (mukhaffafa) and purified by sprinkling water over it?", ["Urine of a boy under two who has only had milk", "Urine of any child under seven", "Blood of a small insect", "Saliva of a cat"], "The Shāfiʿīs class the urine of a male infant under two, fed only on milk, as mukhaffafa and purify it by sprinkling, as in the hadith of Umm Qays. A girl's urine must be washed."],
    de: ["Welche Unreinheit ist bei den Šāfiʿiten „leicht“ (muḫaffafa) und wird durch Besprengen gereinigt?", ["Urin eines Jungen unter zwei Jahren, der nur Milch bekam", "Urin jedes Kindes unter sieben Jahren", "Blut eines kleinen Insekts", "Speichel einer Katze"], "Die Šāfiʿiten zählen den Urin eines männlichen Säuglings unter zwei Jahren, der nur Milch bekam, zur Muḫaffafa und reinigen ihn durch Besprengen, wie im Hadith von Umm Qais. Der Urin eines Mädchens muss gewaschen werden."],
    ar: ["ما النجاسة المخففة عند الشافعية التي تطهر بالنضح؟", ["بول الصبي دون الحولين الذي لم يطعم غير اللبن", "بول كل طفل دون السابعة", "دم الحشرة الصغيرة", "لعاب الهرة"], "النجاسة المخففة عند الشافعية بول الصبي الذي لم يبلغ الحولين ولم يطعم غير اللبن، فيكفي نضحه كما في حديث أم قيس، أما بول الجارية فيُغسل."] },

  { id: "fqs-064", s: "fiqh", g: 3, d: 3, t: ["najasa", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Khalīl ibn Isḥāq, al-Mukhtaṣar, faṣl al-ṭāhir; Ibn Rushd, Bidāyat al-Mujtahid, on the dog",
    en: ["Which school holds that a living dog is pure and that washing a vessel seven times after it licks is an act of worship (taʿabbudī)?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The Mālikīs consider every living animal pure, so the sevenfold washing is worship, not removal of najāsa. The Shāfiʿīs and Ḥanbalīs consider the dog najis and require seven washes, one with earth; the Ḥanafīs treat its saliva like other najāsa."],
    de: ["Welche Schule hält einen lebenden Hund für rein und das siebenmalige Waschen eines Gefäßes nach seinem Lecken für eine reine Gottesdiensthandlung (taʿabbudī)?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Mālikiten halten jedes lebende Tier für rein, das siebenmalige Waschen ist also Gottesdienst, nicht Beseitigung von Unreinheit. Šāfiʿiten und Ḥanbaliten halten den Hund für unrein und verlangen sieben Waschungen, eine mit Erde; die Ḥanafiten behandeln seinen Speichel wie andere Unreinheit."],
    ar: ["أيّ مذهب يرى طهارة الكلب الحي وأن غسل الإناء من ولوغه سبعًا تعبدي؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "كل حي طاهر عند المالكية، فالغسل سبعًا تعبد لا لإزالة نجاسة، والكلب نجس عند الشافعية والحنابلة ويُغسل من ولوغه سبعًا إحداهن بالتراب، ويعامل الحنفية سؤره معاملة سائر النجاسات."] },

  { id: "fqs-065", s: "fiqh", g: 3, d: 4, t: ["water-types", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on water mixed with impurity",
    en: ["Which pair of schools uses the measure of 'two qullas' to decide whether still water becomes impure on contact with najāsa?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "Following the hadith of the two qullas, the Shāfiʿīs and Ḥanbalīs hold that water of that amount is not made impure unless a quality changes. The Ḥanafīs judge by whether the impurity spreads through the water, and the Mālikīs by change only."],
    de: ["Welche beiden Schulen verwenden das Maß von „zwei Qulla“, um zu entscheiden, ob stehendes Wasser durch Kontakt mit Unreinem unrein wird?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Nach dem Hadith der zwei Qulla halten Šāfiʿiten und Ḥanbaliten, dass Wasser dieser Menge nur durch Veränderung einer Eigenschaft unrein wird. Die Ḥanafiten urteilen danach, ob sich die Unreinheit im Wasser ausbreitet, die Mālikiten nur nach Veränderung."],
    ar: ["أيّ مذهبين يعتبران حدّ القلتين في تنجس الماء الراكد بملاقاة النجاسة؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "أخذ الشافعية والحنابلة بحديث القلتين فلا ينجس ما بلغهما إلا بالتغير، واعتبر الحنفية خلوص النجاسة إلى جميع الماء، واعتبر المالكية التغير وحده."] },

  // ---------- Stage 3: ṣalāh ----------
  { id: "fqs-066", s: "fiqh", g: 3, d: 3, t: ["salah-wajibat", "salah-pillars", "madhhab-comparison"], tr: ["hanafi"], src: "al-Marghīnānī, al-Hidāya, bāb ṣifat al-ṣalāt",
    en: ["Which of these is a wājib, not a farḍ, of the prayer in the Ḥanafī school?", ["Reciting al-Fātiḥa", "Standing (qiyām)", "Bowing (rukūʿ)", "Sitting at the end for the length of the tashahhud"], "For the Ḥanafīs the farḍ is reciting some Quran; specifically reciting al-Fātiḥa is wājib, so omitting it by mistake is repaired with sujūd al-sahw. Standing, rukūʿ and the final sitting are farḍ."],
    de: ["Was davon ist in der ḥanafitischen Schule ein Wāǧib und kein Farḍ des Gebets?", ["Die Rezitation der Fātiḥa", "Das Stehen (qiyām)", "Die Verbeugung (rukūʿ)", "Das Schlusssitzen in Länge des Tašahhud"], "Für die Ḥanafiten ist Farḍ das Rezitieren von etwas Koran; die Fātiḥa im Besonderen ist Wāǧib, ihr versehentliches Auslassen wird mit Suǧūd as-Sahw ausgeglichen. Stehen, Verbeugung und Schlusssitzen sind Farḍ."],
    ar: ["أيّ هذه من واجبات الصلاة لا من فرائضها عند الحنفية؟", ["قراءة الفاتحة", "القيام", "الركوع", "القعود الأخير قدر التشهد"], "الفرض عند الحنفية قراءة ما تيسر من القرآن، وتعيين الفاتحة واجب يُجبر تركه سهوًا بسجود السهو، أما القيام والركوع والقعود الأخير ففرائض."] },

  { id: "fqs-067", s: "fiqh", g: 3, d: 4, t: ["salah-pillars", "congregation", "madhhab-comparison"], tr: ["shafii", "comparative"], src: "al-Nawawī, Minhāj al-Ṭālibīn, bāb ṣifat al-ṣalāt",
    en: ["Which school holds that a follower must recite al-Fātiḥa in every rakʿa, even when the imam recites aloud?", ["Shāfiʿī", "Ḥanafī", "Mālikī", "Ḥanbalī"], "The Shāfiʿīs make al-Fātiḥa a pillar for imam, follower and individual alike. The Ḥanafīs say the follower does not recite; the Mālikīs and Ḥanbalīs say he listens in loud prayers and recites (recommended) in quiet ones."],
    de: ["Welche Schule hält, dass der Folgende in jeder Rakʿa die Fātiḥa rezitieren muss, auch wenn der Imam laut rezitiert?", ["Die šāfiʿitische", "Die ḥanafitische", "Die mālikitische", "Die ḥanbalitische"], "Die Šāfiʿiten machen die Fātiḥa zum Pfeiler für Imam, Folgenden und Einzelbetenden. Die Ḥanafiten sagen, der Folgende rezitiert nicht; Mālikiten und Ḥanbaliten: Er hört in lauten Gebeten zu und rezitiert in leisen (empfohlen)."],
    ar: ["أيّ مذهب يوجب على المأموم قراءة الفاتحة في كل ركعة ولو جهر الإمام؟", ["الشافعية", "الحنفية", "المالكية", "الحنابلة"], "الفاتحة ركن عند الشافعية على الإمام والمأموم والمنفرد، ولا يقرأ المأموم عند الحنفية، ويستمع في الجهرية ويُستحب له أن يقرأ في السرية عند المالكية والحنابلة."] },

  { id: "fqs-068", s: "fiqh", g: 3, d: 3, t: ["salah-sunan", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣalāt, on raising the hands",
    en: ["Which pair of schools holds it sunna to raise the hands when going into rukūʿ and when rising from it?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs follow the hadith of Ibn ʿUmar on raising the hands at rukūʿ and rising. The Ḥanafīs, and the Mālikīs in the well-known view, raise them only at the opening takbīr."],
    de: ["Welche beiden Schulen halten das Heben der Hände beim Gang in die Verbeugung und beim Aufrichten daraus für Sunna?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten folgen dem Hadith von Ibn ʿUmar über das Heben der Hände bei Rukūʿ und Aufrichten. Die Ḥanafiten und nach der bekannten Ansicht die Mālikiten heben sie nur beim Eröffnungs-Takbīr."],
    ar: ["أيّ مذهبين يسنّان رفع اليدين عند الركوع والرفع منه؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "أخذ الشافعية والحنابلة بحديث ابن عمر في الرفع عند الركوع والرفع منه، ولا يرفع الحنفية والمالكية في المشهور إلا عند تكبيرة الإحرام."] },

  { id: "fqs-069", s: "fiqh", g: 3, d: 3, t: ["qunut", "madhhab-comparison"], tr: ["maliki", "shafii", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣalāt, on qunūt",
    en: ["Which pair of schools regards qunūt in the Fajr prayer as a regular recommended practice, not only at times of calamity?", ["Mālikī and Shāfiʿī", "Ḥanafī and Ḥanbalī", "Ḥanafī and Mālikī", "Shāfiʿī and Ḥanbalī"], "The Mālikīs (quietly, before rukūʿ) and the Shāfiʿīs (after rising from rukūʿ in the second rakʿa) make qunūt in Fajr regular. The Ḥanafīs and Ḥanbalīs limit qunūt in obligatory prayers to calamities (nawāzil)."],
    de: ["Welche beiden Schulen sehen das Qunūt im Faǧr-Gebet als regelmäßige Empfehlung, nicht nur in Notzeiten?", ["Mālikiten und Šāfiʿiten", "Ḥanafiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Šāfiʿiten und Ḥanbaliten"], "Die Mālikiten (leise, vor dem Rukūʿ) und die Šāfiʿiten (nach dem Aufrichten in der zweiten Rakʿa) machen das Qunūt im Faǧr regelmäßig. Ḥanafiten und Ḥanbaliten beschränken es in Pflichtgebeten auf Notlagen (nawāzil)."],
    ar: ["أيّ مذهبين يستحبان القنوت في الفجر دائمًا لا في النوازل فقط؟", ["المالكية والشافعية", "الحنفية والحنابلة", "الحنفية والمالكية", "الشافعية والحنابلة"], "يقنت المالكية في الصبح سرًّا قبل الركوع، والشافعية بعد الرفع من ركوع الثانية، ويقصر الحنفية والحنابلة القنوت في الفرائض على النوازل."] },

  { id: "fqs-070", s: "fiqh", g: 3, d: 4, t: ["witr", "qunut", "madhhab-comparison"], tr: ["hanafi"], src: "al-Qudūrī, al-Mukhtaṣar, bāb ṣalāt al-witr",
    en: ["How is witr prayed in the Ḥanafī school?", ["Three rakʿas with one salām, qunūt before rukūʿ in the third, all year", "One rakʿa alone, qunūt after rukūʿ in Ramaḍān only", "Three rakʿas with two salāms, no qunūt", "Any odd number up to eleven, qunūt optional"], "The Ḥanafīs pray witr as three rakʿas with one salām and a sitting after the second; before the rukūʿ of the third they say takbīr and recite qunūt throughout the year."],
    de: ["Wie wird Witr in der ḥanafitischen Schule gebetet?", ["Drei Rakʿas mit einem Salām, Qunūt vor dem Rukūʿ der dritten, ganzjährig", "Eine einzelne Rakʿa, Qunūt nach dem Rukūʿ nur im Ramaḍān", "Drei Rakʿas mit zwei Salāms, ohne Qunūt", "Jede ungerade Zahl bis elf, Qunūt freiwillig"], "Die Ḥanafiten beten Witr als drei Rakʿas mit einem Salām und einem Sitzen nach der zweiten; vor dem Rukūʿ der dritten sprechen sie den Takbīr und das Qunūt, das ganze Jahr hindurch."],
    ar: ["كيف يُصلّى الوتر عند الحنفية؟", ["ثلاث بتسليمة واحدة والقنوت قبل ركوع الثالثة طوال السنة", "ركعة واحدة والقنوت بعد الركوع في رمضان فقط", "ثلاث بتسليمتين بلا قنوت", "أيّ وتر إلى إحدى عشرة والقنوت اختياري"], "الوتر عند الحنفية ثلاث ركعات بتسليمة واحدة يقعد على رأس الثانية، ويكبّر قبل ركوع الثالثة ويقنت في جميع السنة."] },

  { id: "fqs-071", s: "fiqh", g: 3, d: 4, t: ["sujud-sahw", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Ibn Abī Zayd al-Qayrawānī, al-Risāla, bāb sujūd al-sahw",
    en: ["What is the Mālikī rule on where sujūd al-sahw is placed?", ["Before salām for an omission, after salām for an addition", "Always after salām", "Always before salām", "Before salām only if the imam forgot"], "The Mālikīs prostrate before salām when something is lacking and after salām when something was added, and before salām if both occurred. The Shāfiʿīs always prostrate before salām, the Ḥanafīs after it."],
    de: ["Was ist die mālikitische Regel für den Platz des Suǧūd as-Sahw?", ["Vor dem Salām bei Auslassung, danach bei Hinzufügung", "Immer nach dem Salām", "Immer vor dem Salām", "Vor dem Salām nur, wenn der Imam vergaß"], "Die Mālikiten werfen sich vor dem Salām nieder, wenn etwas fehlt, und danach, wenn etwas hinzugefügt wurde; bei beidem vor dem Salām. Die Šāfiʿiten tun es immer davor, die Ḥanafiten danach."],
    ar: ["ما قاعدة المالكية في محل سجود السهو؟", ["قبل السلام للنقص وبعده للزيادة", "بعد السلام دائمًا", "قبل السلام دائمًا", "قبل السلام إن سها الإمام فقط"], "يسجد المالكية قبل السلام للنقص وبعده للزيادة، فإن اجتمعا فقبله، ويسجد الشافعية قبله مطلقًا، والحنفية بعده."] },

  { id: "fqs-072", s: "fiqh", g: 3, d: 4, t: ["qasr-jam", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb ṣalāt al-musāfir",
    en: ["How do the Ḥanafīs define the minimum distance of a journey that allows shortening?", ["Three days' travel at a moderate pace", "One day and night of travel", "Any journey that people call travel", "Two days' travel by camel"], "The Ḥanafīs set the minimum at a journey of three days at a moderate pace. The other three schools set four burud (sixteen farsakhs), roughly two days' travel; later scholars give approximate kilometre equivalents."],
    de: ["Wie bestimmen die Ḥanafiten die Mindestentfernung einer Reise, die das Verkürzen erlaubt?", ["Drei Tagesreisen in gemäßigtem Tempo", "Eine Reise von einem Tag und einer Nacht", "Jede Reise, die man gemeinhin Reise nennt", "Zwei Tagesreisen auf dem Kamel"], "Die Ḥanafiten setzen als Minimum eine Reise von drei Tagen in gemäßigtem Tempo. Die anderen drei Schulen setzen vier Burud (sechzehn Farsach), etwa zwei Tagesreisen; spätere Gelehrte nennen ungefähre Entsprechungen in Kilometern."],
    ar: ["ما مسافة القصر عند الحنفية؟", ["مسيرة ثلاثة أيام بالسير الوسط", "مسيرة يوم وليلة", "كل ما يسمى سفرًا عرفًا", "مسيرة يومين على الإبل"], "مسافة القصر عند الحنفية مسيرة ثلاثة أيام بسير وسط، وعند الثلاثة أربعة برد وهي ستة عشر فرسخًا، وقدّرها المتأخرون بالكيلومترات تقريبًا."] },

  { id: "fqs-073", s: "fiqh", g: 3, d: 4, t: ["qasr-jam", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Qudūrī, al-Mukhtaṣar, bāb ṣalāt al-musāfir",
    en: ["According to the Ḥanafī school, an intention to stay in a town for how long makes the traveller a resident who prays in full?", ["Fifteen days or more", "Four days or more", "More than twenty prayers", "Three days or more"], "The Ḥanafīs make an intention of fifteen days or more end the journey's concession. The Mālikīs and Shāfiʿīs set four days (not counting arrival and departure), and the Ḥanbalīs more than twenty prayers."],
    de: ["Ab welcher beabsichtigten Aufenthaltsdauer in einem Ort wird der Reisende nach der ḥanafitischen Schule zum Ansässigen, der vollständig betet?", ["Fünfzehn Tage oder mehr", "Vier Tage oder mehr", "Mehr als zwanzig Gebete", "Drei Tage oder mehr"], "Bei den Ḥanafiten beendet die Absicht von fünfzehn Tagen oder mehr die Reiseerleichterung. Mālikiten und Šāfiʿiten setzen vier Tage (ohne An- und Abreisetag), die Ḥanbaliten mehr als zwanzig Gebete."],
    ar: ["كم مدة الإقامة التي إذا نواها المسافر عند الحنفية أتمّ الصلاة؟", ["خمسة عشر يومًا فأكثر", "أربعة أيام فأكثر", "أكثر من عشرين صلاة", "ثلاثة أيام فأكثر"], "نية إقامة خمسة عشر يومًا فأكثر تقطع رخصة السفر عند الحنفية، وأربعة أيام سوى يومي الدخول والخروج عند المالكية والشافعية، وأكثر من عشرين صلاة عند الحنابلة."] },

  { id: "fqs-074", s: "fiqh", g: 3, d: 4, t: ["jumuah", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Jumuʿa, on the number required",
    en: ["Which pair of schools requires forty men of those obliged for the Friday prayer to be valid?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs require forty obliged men including the imam. Abū Ḥanīfa required three besides the imam, and the Mālikīs twelve besides the imam."],
    de: ["Welche beiden Schulen verlangen für die Gültigkeit des Freitagsgebets vierzig verpflichtete Männer?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten verlangen vierzig verpflichtete Männer einschließlich des Imams. Abū Ḥanīfa verlangte drei außer dem Imam, die Mālikiten zwölf außer dem Imam."],
    ar: ["أيّ مذهبين يشترطان لصحة الجمعة أربعين رجلًا من أهل وجوبها؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "يشترط الشافعية والحنابلة أربعين من أهل الوجوب بالإمام، واشترط أبو حنيفة ثلاثة سوى الإمام، والمالكية اثني عشر سوى الإمام."] },

  { id: "fqs-075", s: "fiqh", g: 3, d: 4, t: ["eid", "madhhab-comparison"], tr: ["hanbali", "comparative"], src: "Ibn Qudāma, ʿUmdat al-Fiqh, bāb ṣalāt al-ʿīdayn",
    en: ["Which school holds that the ʿĪd prayer is a communal obligation (farḍ kifāya)?", ["Ḥanbalī", "Ḥanafī", "Mālikī", "Shāfiʿī"], "The Ḥanbalīs make the ʿĪd prayer farḍ kifāya. The Ḥanafīs hold it wājib on those obliged to attend Jumuʿa, and the Mālikīs and Shāfiʿīs an emphasised sunna."],
    de: ["Welche Schule hält das ʿĪd-Gebet für eine Gemeinschaftspflicht (farḍ kifāya)?", ["Die ḥanbalitische", "Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische"], "Die Ḥanbaliten machen das ʿĪd-Gebet zur Farḍ Kifāya. Die Ḥanafiten halten es für wāǧib für alle, die zur Ǧumuʿa verpflichtet sind, Mālikiten und Šāfiʿiten für eine bekräftigte Sunna."],
    ar: ["أيّ مذهب يرى صلاة العيد فرض كفاية؟", ["الحنابلة", "الحنفية", "المالكية", "الشافعية"], "صلاة العيد فرض كفاية عند الحنابلة، وواجبة على من تجب عليه الجمعة عند الحنفية، وسنة مؤكدة عند المالكية والشافعية."] },

  { id: "fqs-076", s: "fiqh", g: 3, d: 4, t: ["janazah", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Janāʾiz, on recitation in the funeral prayer",
    en: ["Which pair of schools makes reciting al-Fātiḥa after the first takbīr a pillar of the funeral prayer?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs cite Ibn ʿAbbās reciting al-Fātiḥa in the funeral prayer and calling it sunna. The Ḥanafīs say it is not recited as Quran (only as praise), and the Mālikīs consider it disliked."],
    de: ["Welche beiden Schulen machen die Rezitation der Fātiḥa nach dem ersten Takbīr zu einem Pfeiler des Totengebets?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten verweisen auf Ibn ʿAbbās, der im Totengebet die Fātiḥa rezitierte und es Sunna nannte. Die Ḥanafiten sagen, sie wird nicht als Koranrezitation gesprochen (nur als Lobpreis), die Mālikiten halten sie für verpönt."],
    ar: ["أيّ مذهبين يجعلان قراءة الفاتحة بعد التكبيرة الأولى ركنًا في صلاة الجنازة؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "استدل الشافعية والحنابلة بقراءة ابن عباس الفاتحة على الجنازة وقوله إنها سنة، ولا تُقرأ عند الحنفية بنية القراءة بل الثناء، وتُكره عند المالكية."] },

  { id: "fqs-077", s: "fiqh", g: 3, d: 4, t: ["congregation", "madhhab-comparison"], tr: ["hanbali", "comparative"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣalāt, bāb ṣalāt al-jamāʿa",
    en: ["Which school holds that praying the obligatory prayers in congregation is an individual obligation (farḍ ʿayn) on capable men?", ["Ḥanbalī", "Ḥanafī", "Mālikī", "Shāfiʿī"], "The Ḥanbalīs make congregation farḍ ʿayn, though a prayer alone is still valid. The Shāfiʿīs (soundest view) say farḍ kifāya, and the Ḥanafīs and Mālikīs an emphasised sunna, which many later Ḥanafīs call wājib."],
    de: ["Welche Schule hält das gemeinschaftliche Verrichten der Pflichtgebete für eine individuelle Pflicht (farḍ ʿain) fähiger Männer?", ["Die ḥanbalitische", "Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische"], "Die Ḥanbaliten machen die Gemeinschaft zur Farḍ ʿAin, das Einzelgebet bleibt aber gültig. Die Šāfiʿiten sagen (stärkste Ansicht) Farḍ Kifāya, Ḥanafiten und Mālikiten bekräftigte Sunna, die viele spätere Ḥanafiten wāǧib nennen."],
    ar: ["أيّ مذهب يرى صلاة الجماعة في الفرائض فرض عين على الرجال القادرين؟", ["الحنابلة", "الحنفية", "المالكية", "الشافعية"], "الجماعة فرض عين عند الحنابلة مع صحة صلاة المنفرد، وفرض كفاية عند الشافعية في الأصح، وسنة مؤكدة عند الحنفية والمالكية، وعبّر كثير من متأخري الحنفية بالوجوب."] },

  { id: "fqs-078", s: "fiqh", g: 3, d: 3, t: ["salah-sunan", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Khalīl ibn Isḥāq, al-Mukhtaṣar, faṣl sunan al-ṣalāt wa-mandūbātihā",
    en: ["Which school is known, in its well-known view, for letting the arms hang at the sides (sadl) in the obligatory prayer?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The well-known Mālikī view is sadl in obligatory prayers, with placing the hands allowed in voluntary ones. The Ḥanafīs and Ḥanbalīs place the right hand over the left below the navel, the Shāfiʿīs below the chest."],
    de: ["Welche Schule ist nach ihrer bekannten Ansicht dafür bekannt, im Pflichtgebet die Arme seitlich herabhängen zu lassen (sadl)?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die bekannte mālikitische Ansicht ist Sadl im Pflichtgebet, im freiwilligen ist das Verschränken erlaubt. Ḥanafiten und Ḥanbaliten legen die Rechte unter dem Nabel auf die Linke, die Šāfiʿiten unter der Brust."],
    ar: ["أيّ مذهب عُرف في المشهور بإرسال اليدين (السدل) في الفريضة؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "المشهور عند المالكية السدل في الفريضة وجواز القبض في النافلة، ويضع الحنفية والحنابلة اليمنى على اليسرى تحت السرة، والشافعية تحت الصدر."] },

  { id: "fqs-079", s: "fiqh", g: 3, d: 3, t: ["sujud-tilawah", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb sujūd al-tilāwa",
    en: ["Which school holds that the prostration of recitation (sujūd al-tilāwa) is wājib?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "The Ḥanafīs make it wājib on the reciter and the listener. The other three schools hold it sunna, citing ʿUmar, who said on the minbar that Allah had not made it obligatory unless one wishes."],
    de: ["Welche Schule hält die Niederwerfung bei der Rezitation (suǧūd at-tilāwa) für wāǧib?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Ḥanafiten machen sie für Rezitierenden und Zuhörer wāǧib. Die anderen drei Schulen halten sie für Sunna und verweisen auf ʿUmar, der auf der Kanzel sagte, Allah habe sie nicht vorgeschrieben, außer man wolle."],
    ar: ["أيّ مذهب يرى سجود التلاوة واجبًا؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "سجود التلاوة واجب عند الحنفية على التالي والسامع، وسنة عند الثلاثة لقول عمر على المنبر إن الله لم يفرضه إلا أن نشاء."] },

  // ---------- Stage 4 ----------
  { id: "fqs-080", s: "fiqh", g: 4, d: 4, t: ["wudu-sunan", "madhhab-comparison"], tr: ["hanbali", "comparative"], src: "al-Ḥajjāwī, Zād al-Mustaqniʿ, bāb farḍ al-wuḍūʾ wa-ṣifatih; Ibn Qudāma, al-Mughnī, on the tasmiya",
    en: ["Which school, in its relied-upon position, holds that saying bismillāh at the start of wuḍūʾ is obligatory when one remembers it?", ["Ḥanbalī", "Ḥanafī", "Mālikī", "Shāfiʿī"], "The later Ḥanbalī relied-upon view makes the tasmiya wājib, dropping it if forgotten, based on the hadith 'no wuḍūʾ for one who does not mention Allah's name'. Al-Mughnī reports another narration from Aḥmad that it is sunna, the view of the other three schools."],
    de: ["Welche Schule hält nach ihrer maßgeblichen Position das Sprechen der Basmala zu Beginn der Waschung für Pflicht, wenn man daran denkt?", ["Die ḥanbalitische", "Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische"], "Die maßgebliche spätere ḥanbalitische Ansicht macht die Tasmiya wāǧib und lässt sie bei Vergessen entfallen, gestützt auf den Hadith „keine Waschung für den, der Allahs Namen nicht nennt“. Al-Muġnī berichtet eine andere Überlieferung von Aḥmad, nach der sie Sunna ist, wie bei den anderen drei Schulen."],
    ar: ["أيّ مذهب يرى في المعتمد وجوب التسمية في أول الوضوء مع الذكر؟", ["الحنابلة", "الحنفية", "المالكية", "الشافعية"], "المعتمد عند متأخري الحنابلة وجوب التسمية وسقوطها بالنسيان لحديث لا وضوء لمن لم يذكر اسم الله عليه، وذكر في المغني رواية أخرى عن أحمد بأنها سنة، وهو قول الثلاثة."] },

  { id: "fqs-081", s: "fiqh", g: 4, d: 5, t: ["tayammum", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb al-tayammum",
    en: ["Which school treats tayammum as a full substitute for wuḍūʾ, so that one tayammum remains valid for several obligatory prayers, even across prayer times, until water is found or a nullifier occurs?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "For the Ḥanafīs tayammum lifts the ḥadath until water is found, so it acts like wuḍūʾ. The Mālikīs and Shāfiʿīs require a new tayammum for each obligatory prayer, and the Ḥanbalīs hold it ends when the prayer time leaves."],
    de: ["Welche Schule sieht Tayammum als vollen Ersatz der Waschung, sodass ein Tayammum für mehrere Pflichtgebete, auch über Gebetszeiten hinweg, gilt, bis Wasser gefunden wird oder ein Brecher eintritt?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Für die Ḥanafiten hebt Tayammum die Unreinheit auf, bis Wasser gefunden wird, und wirkt daher wie die Waschung. Mālikiten und Šāfiʿiten verlangen für jedes Pflichtgebet ein neues Tayammum, die Ḥanbaliten lassen es mit dem Ende der Gebetszeit enden."],
    ar: ["أيّ مذهب يجعل التيمم بدلًا مطلقًا عن الوضوء فيُصلّى به فرائض متعددة ولو في أوقات مختلفة حتى يجد الماء أو ينتقض؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "التيمم عند الحنفية رافع للحدث إلى وجود الماء فهو كالوضوء، ويوجب المالكية والشافعية تيممًا لكل فريضة، ويبطل عند الحنابلة بخروج الوقت."] },

  { id: "fqs-082", s: "fiqh", g: 4, d: 4, t: ["masah-khuffayn", "madhhab-comparison"], tr: ["hanafi", "shafii", "hanbali"], src: "al-Nawawī, Minhāj al-Ṭālibīn, bāb masḥ al-khuff; al-Qudūrī, al-Mukhtaṣar, bāb al-masḥ ʿalā al-khuffayn",
    en: ["In the relied-upon views of the Ḥanafī, Shāfiʿī and Ḥanbalī schools, from when is the masḥ period counted?", ["From the first ḥadath after putting them on", "From the moment they are put on", "From the first wiping", "From the start of the next prayer time"], "The period runs from the first ḥadath after wearing the khuffs in purity, since that is when masḥ becomes possible. A narration from Aḥmad counts from the first wiping, a view some later scholars preferred, but it is not the relied-upon position of these schools."],
    de: ["Ab wann wird die Masḥ-Frist nach den maßgeblichen Ansichten der Ḥanafiten, Šāfiʿiten und Ḥanbaliten gezählt?", ["Ab dem ersten Ḥadaṯ nach dem Anziehen", "Ab dem Moment des Anziehens", "Ab dem ersten Bestreichen", "Ab Beginn der nächsten Gebetszeit"], "Die Frist läuft ab dem ersten Ḥadaṯ nach dem Anziehen im Reinheitszustand, denn ab dann ist Masḥ möglich. Eine Überlieferung von Aḥmad zählt ab dem ersten Bestreichen, was einige spätere Gelehrte bevorzugten, doch ist es nicht die maßgebliche Position dieser Schulen."],
    ar: ["من متى تُحسب مدة المسح على المعتمد عند الحنفية والشافعية والحنابلة؟", ["من أول حدث بعد اللبس", "من وقت اللبس", "من أول مسح", "من أول وقت الصلاة التالية"], "تبدأ المدة من الحدث بعد اللبس على طهارة لأنه وقت جواز المسح، وفي رواية عن أحمد من أول مسح واختارها بعض المحققين، لكنها ليست المعتمد في هذه المذاهب."] },

  { id: "fqs-083", s: "fiqh", g: 4, d: 5, t: ["masah-khuffayn", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb al-masḥ ʿalā al-khuffayn",
    en: ["A man washes his right foot and puts on the right khuff, then washes the left foot and puts on the left khuff, completing his wuḍūʾ. Which school allows him to wipe over both after a later ḥadath?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "The Ḥanafīs require only that the purity be complete at the time of the first ḥadath, which it is. The Mālikīs, Shāfiʿīs and Ḥanbalīs require complete purity before putting on the khuffs, so the first khuff must be removed and put on again."],
    de: ["Ein Mann wäscht den rechten Fuß und zieht den rechten Ḫuff an, wäscht dann den linken Fuß und zieht den linken an und vollendet so die Waschung. Welche Schule erlaubt ihm nach einem späteren Ḥadaṯ das Bestreichen beider?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Ḥanafiten verlangen nur, dass die Reinheit zum Zeitpunkt des ersten Ḥadaṯ vollständig ist, was hier zutrifft. Mālikiten, Šāfiʿiten und Ḥanbaliten verlangen vollständige Reinheit vor dem Anziehen, daher muss der erste Ḫuff aus- und wieder angezogen werden."],
    ar: ["غسل رجل رجله اليمنى فلبس خفها، ثم غسل اليسرى فلبس خفها فأتمّ وضوءه. أيّ مذهب يجيز له المسح بعد الحدث؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "يشترط الحنفية كمال الطهارة وقت الحدث وقد وُجد، ويشترط المالكية والشافعية والحنابلة كمالها قبل اللبس، فيلزمه نزع الأول ثم لبسه."] },

  { id: "fqs-084", s: "fiqh", g: 4, d: 4, t: ["hayd-nifas", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Khalīl ibn Isḥāq, al-Mukhtaṣar, faṣl al-ḥayḍ",
    en: ["Which school, in its well-known view, permits a menstruating woman to recite the Quran from memory while the bleeding continues?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The Mālikīs permit it during the bleeding, as she cannot remove her state at will, but not after the blood stops and before ghusl. The Ḥanafīs, Shāfiʿīs and Ḥanbalīs forbid her to recite, like the junub."],
    de: ["Welche Schule erlaubt nach ihrer bekannten Ansicht einer menstruierenden Frau, während der Blutung auswendig Koran zu rezitieren?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Mālikiten erlauben es während der Blutung, da sie ihren Zustand nicht selbst beenden kann, nicht aber nach dem Ende der Blutung vor dem Ġusl. Ḥanafiten, Šāfiʿiten und Ḥanbaliten verbieten ihr das Rezitieren wie dem Ǧunub."],
    ar: ["أيّ مذهب يجيز في المشهور للحائض قراءة القرآن عن ظهر قلب ما دام الدم مستمرًا؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "أجاز المالكية للحائض القراءة حال نزول الدم لأنها لا تملك رفع حدثها، لا بعد انقطاعه وقبل الغسل، ومنعها الحنفية والشافعية والحنابلة كالجنب."] },

  { id: "fqs-085", s: "fiqh", g: 4, d: 5, t: ["water-types", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Khalīl ibn Isḥāq, al-Mukhtaṣar, bāb al-ṭahāra; Ibn Rushd, Bidāyat al-Mujtahid, on used water",
    en: ["Which school holds that water already used to lift a ḥadath (māʾ mustaʿmal) remains purifying, though its use is disliked?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The Mālikīs keep used water ṭahūr with dislike when other water exists. The Ḥanafīs (the view given fatwā), Shāfiʿīs and Ḥanbalīs consider it pure but no longer purifying; the latter two apply this when it is less than two qullas."],
    de: ["Welche Schule hält Wasser, das bereits zur Aufhebung eines Ḥadaṯ benutzt wurde (māʾ mustaʿmal), weiterhin für reinigend, wenn auch verpönt?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Mālikiten lassen benutztes Wasser ṭahūr, mit Verpöntheit, wenn anderes Wasser vorhanden ist. Ḥanafiten (Fatwā-Ansicht), Šāfiʿiten und Ḥanbaliten halten es für rein, aber nicht mehr reinigend; die beiden Letzteren, wenn es weniger als zwei Qulla sind."],
    ar: ["أيّ مذهب يرى الماء المستعمل في رفع الحدث باقيًا على طهوريته مع الكراهة؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "الماء المستعمل طهور مكروه عند المالكية مع وجود غيره، وهو عند الحنفية على المفتى به والشافعية والحنابلة طاهر غير مطهِّر، ويقيّده الشافعية والحنابلة بما دون القلتين."] },

  { id: "fqs-086", s: "fiqh", g: 4, d: 5, t: ["water-types", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṭahāra, on water mixed with impurity",
    en: ["Which school holds, in its well-known view, that water, small or large, becomes impure only if its colour, taste or smell changes from the najāsa?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The Mālikīs rely on the hadith that water is pure and nothing makes it impure, and apply only the criterion of change, while disliking small water that a little najāsa fell into. The Shāfiʿīs and Ḥanbalīs distinguish by two qullas, and the Ḥanafīs by large and small water."],
    de: ["Welche Schule hält nach ihrer bekannten Ansicht, dass Wasser, ob wenig oder viel, nur unrein wird, wenn sich Farbe, Geschmack oder Geruch durch die Unreinheit ändern?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Mālikiten stützen sich auf den Hadith, dass Wasser rein ist und nichts es verunreinigt, und wenden nur das Kriterium der Veränderung an, halten aber wenig Wasser mit etwas Unreinem für verpönt. Šāfiʿiten und Ḥanbaliten unterscheiden nach zwei Qulla, die Ḥanafiten nach viel und wenig Wasser."],
    ar: ["أيّ مذهب يرى في المشهور أن الماء قليلًا كان أو كثيرًا لا ينجس إلا بتغير لونه أو طعمه أو ريحه بالنجاسة؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "أخذ المالكية بحديث الماء طهور لا ينجسه شيء فاعتبروا التغير وحده مع كراهة القليل الذي حلّته نجاسة يسيرة، وفرّق الشافعية والحنابلة بالقلتين والحنفية بين القليل والكثير."] },

  { id: "fqs-087", s: "fiqh", g: 4, d: 4, t: ["salah-wajibat", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb ṣifat al-ṣalāt",
    en: ["How do the Ḥanafīs classify the closing salām of the prayer, unlike the other three schools?", ["As wājib, not farḍ", "As farḍ, like the others", "As a mere sunna", "As a condition of the prayer"], "For the Ḥanafīs the word al-salām is wājib, so the prayer is complete once the final sitting is done, even if something else ends it, though leaving the salām is sinful. The other schools make the taslīm a pillar."],
    de: ["Wie ordnen die Ḥanafiten, anders als die übrigen drei Schulen, den abschließenden Salām des Gebets ein?", ["Als wāǧib, nicht farḍ", "Als farḍ wie die anderen", "Als bloße Sunna", "Als Bedingung des Gebets"], "Für die Ḥanafiten ist das Wort as-salām wāǧib; das Gebet ist mit dem Schlusssitzen vollendet, auch wenn etwas anderes es beendet, das Auslassen des Salām ist aber Sünde. Die anderen Schulen machen den Taslīm zum Pfeiler."],
    ar: ["كيف يصنّف الحنفية التسليم في آخر الصلاة بخلاف المذاهب الثلاثة؟", ["واجب لا فرض", "فرض كغيرهم", "سنة فقط", "شرط من شروط الصلاة"], "لفظ السلام عند الحنفية واجب، فتتم الصلاة بالقعود الأخير ولو خرج منها بغيره مع الإثم، وجعله الثلاثة ركنًا."] },

  { id: "fqs-088", s: "fiqh", g: 4, d: 5, t: ["salah-pillars", "salah-wajibat", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb ṣifat al-ṣalāt, on ṭumaʾnīna",
    en: ["Which jurists held that stillness (ṭumaʾnīna) in rukūʿ and sujūd is not a pillar of the prayer but below it in rank?", ["Abū Ḥanīfa and Muḥammad al-Shaybānī", "Abū Yūsuf and al-Shāfiʿī", "Mālik and Aḥmad", "al-Shāfiʿī and Aḥmad"], "Abū Ḥanīfa and Muḥammad did not make ṭumaʾnīna a farḍ; later Ḥanafīs class it as wājib. Abū Yūsuf, with al-Shāfiʿī and Aḥmad, made it a farḍ, citing the hadith of the man who prayed badly."],
    de: ["Welche Juristen hielten die Ruhe (ṭumaʾnīna) in Rukūʿ und Suǧūd nicht für einen Pfeiler des Gebets, sondern für rangniedriger?", ["Abū Ḥanīfa und Muḥammad aš-Šaibānī", "Abū Yūsuf und aš-Šāfiʿī", "Mālik und Aḥmad", "aš-Šāfiʿī und Aḥmad"], "Abū Ḥanīfa und Muḥammad machten die Ṭumaʾnīna nicht zum Farḍ; spätere Ḥanafiten stufen sie als wāǧib ein. Abū Yūsuf machte sie mit aš-Šāfiʿī und Aḥmad zum Farḍ, gestützt auf den Hadith des Mannes, der schlecht betete."],
    ar: ["مَن مِن الفقهاء لم يجعل الطمأنينة في الركوع والسجود ركنًا بل دونه؟", ["أبو حنيفة ومحمد بن الحسن", "أبو يوسف والشافعي", "مالك وأحمد", "الشافعي وأحمد"], "لم يجعل أبو حنيفة ومحمد الطمأنينة فرضًا وصنّفها متأخرو الحنفية واجبًا، وجعلها أبو يوسف مع الشافعي وأحمد فرضًا لحديث المسيء صلاته."] },

  { id: "fqs-089", s: "fiqh", g: 4, d: 5, t: ["witr", "qunut", "madhhab-comparison"], tr: ["shafii"], src: "al-Nawawī, Minhāj al-Ṭālibīn, bāb ṣalāt al-nafl",
    en: ["In the Shāfiʿī school, when is qunūt in the witr prayer a sunna?", ["In the second half of Ramaḍān", "Throughout the year", "During the whole of Ramaḍān", "Only in the last ten nights of Ramaḍān"], "Al-Nawawī states that qunūt in witr is recommended in the second half of Ramaḍān, after rising from rukūʿ in the last rakʿa. The Ḥanafīs make qunūt in witr all year, before rukūʿ."],
    de: ["Wann ist das Qunūt im Witr-Gebet in der šāfiʿitischen Schule Sunna?", ["In der zweiten Hälfte des Ramaḍān", "Das ganze Jahr hindurch", "Im ganzen Ramaḍān", "Nur in den letzten zehn Nächten des Ramaḍān"], "An-Nawawī stellt fest, dass das Qunūt im Witr in der zweiten Hälfte des Ramaḍān empfohlen ist, nach dem Aufrichten vom Rukūʿ der letzten Rakʿa. Die Ḥanafiten sprechen es das ganze Jahr vor dem Rukūʿ."],
    ar: ["متى يُسنّ القنوت في الوتر عند الشافعية؟", ["في النصف الثاني من رمضان", "في جميع السنة", "في رمضان كله", "في العشر الأواخر من رمضان فقط"], "ذكر النووي أنه يُستحب القنوت في الوتر في النصف الأخير من رمضان بعد الرفع من ركوع الركعة الأخيرة، ويقنت الحنفية في الوتر طوال السنة قبل الركوع."] },

  { id: "fqs-090", s: "fiqh", g: 4, d: 5, t: ["adhan-iqama", "madhhab-comparison"], tr: ["maliki", "shafii", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣalāt, bāb al-adhān",
    en: ["Which pair of schools holds tarjīʿ in the adhān as sunna, saying the two testimonies quietly first and then aloud, following the adhān taught to Abū Maḥdhūra?", ["Mālikī and Shāfiʿī", "Ḥanafī and Ḥanbalī", "Ḥanafī and Mālikī", "Shāfiʿī and Ḥanbalī"], "The Mālikīs and Shāfiʿīs follow the adhān of Abū Maḥdhūra with tarjīʿ. The Ḥanafīs and Ḥanbalīs follow the adhān of Bilāl without it."],
    de: ["Welche beiden Schulen halten den Tarǧīʿ im Adhān für Sunna, also die beiden Bezeugungen erst leise, dann laut, nach dem Adhān, den Abū Maḥḏūra gelehrt bekam?", ["Mālikiten und Šāfiʿiten", "Ḥanafiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Šāfiʿiten und Ḥanbaliten"], "Mālikiten und Šāfiʿiten folgen dem Adhān von Abū Maḥḏūra mit Tarǧīʿ. Ḥanafiten und Ḥanbaliten folgen dem Adhān von Bilāl ohne ihn."],
    ar: ["أيّ مذهبين يسنّان الترجيع في الأذان، وهو الإتيان بالشهادتين سرًّا ثم جهرًا، أخذًا بأذان أبي محذورة؟", ["المالكية والشافعية", "الحنفية والحنابلة", "الحنفية والمالكية", "الشافعية والحنابلة"], "أخذ المالكية والشافعية بأذان أبي محذورة وفيه الترجيع، وأخذ الحنفية والحنابلة بأذان بلال بلا ترجيع."] },

  { id: "fqs-091", s: "fiqh", g: 4, d: 5, t: ["adhan-iqama", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb al-adhān",
    en: ["Which jurists held that an adhān for Fajr given before its time is not valid and must be repeated after dawn?", ["Abū Ḥanīfa and Muḥammad", "Mālik and al-Shāfiʿī", "Aḥmad and Abū Yūsuf", "al-Shāfiʿī and Aḥmad"], "Abū Ḥanīfa and Muḥammad allow no adhān before the time for any prayer. Abū Yūsuf, with Mālik, al-Shāfiʿī and Aḥmad, permits it for Fajr, citing Bilāl's call at night followed by Ibn Umm Maktūm's."],
    de: ["Welche Juristen hielten einen Adhān für Faǧr vor dessen Zeit für ungültig, sodass er nach der Morgendämmerung zu wiederholen ist?", ["Abū Ḥanīfa und Muḥammad", "Mālik und aš-Šāfiʿī", "Aḥmad und Abū Yūsuf", "aš-Šāfiʿī und Aḥmad"], "Abū Ḥanīfa und Muḥammad erlauben für kein Gebet einen Adhān vor der Zeit. Abū Yūsuf erlaubt ihn mit Mālik, aš-Šāfiʿī und Aḥmad für Faǧr, gestützt auf Bilāls Ruf in der Nacht, auf den der von Ibn Umm Maktūm folgte."],
    ar: ["مَن مِن الفقهاء لم يعتدّ بأذان الفجر قبل وقته وأوجب إعادته بعد الفجر؟", ["أبو حنيفة ومحمد", "مالك والشافعي", "أحمد وأبو يوسف", "الشافعي وأحمد"], "لا يجيز أبو حنيفة ومحمد الأذان قبل الوقت لأي صلاة، وأجازه أبو يوسف مع مالك والشافعي وأحمد للفجر لحديث أذان بلال بليل ثم ابن أم مكتوم."] },

  { id: "fqs-092", s: "fiqh", g: 4, d: 5, t: ["qasr-jam", "madhhab-comparison"], tr: ["shafii", "comparative"], src: "al-Nawawī, Minhāj al-Ṭālibīn, bāb ṣalāt al-musāfir, on combining for rain",
    en: ["Which school allows combining Ẓuhr with ʿAṣr, and not only Maghrib with ʿIshāʾ, because of rain?", ["Shāfiʿī", "Mālikī", "Ḥanbalī", "Ḥanafī"], "The Shāfiʿīs allow rain-combining for both pairs, only in the time of the first prayer and for those praying in a congregation reached with difficulty. The Mālikīs and Ḥanbalīs restrict it to Maghrib and ʿIshāʾ; the Ḥanafīs do not allow it."],
    de: ["Welche Schule erlaubt wegen Regen das Zusammenlegen von Ẓuhr mit ʿAṣr und nicht nur von Maġrib mit ʿIšāʾ?", ["Die šāfiʿitische", "Die mālikitische", "Die ḥanbalitische", "Die ḥanafitische"], "Die Šāfiʿiten erlauben das Regen-Zusammenlegen für beide Paare, nur in der Zeit des ersten Gebets und für Gemeinschaftsbeter mit beschwerlichem Weg. Mālikiten und Ḥanbaliten beschränken es auf Maġrib und ʿIšāʾ; die Ḥanafiten erlauben es nicht."],
    ar: ["أيّ مذهب يجيز الجمع للمطر بين الظهر والعصر لا بين المغرب والعشاء فحسب؟", ["الشافعية", "المالكية", "الحنابلة", "الحنفية"], "يجيز الشافعية الجمع بالمطر في الصلاتين جمع تقديم فقط لمن يصلي جماعة في مكان بعيد يتأذى بالمطر في طريقه، وقصره المالكية والحنابلة على المغرب والعشاء، ولا يجيزه الحنفية."] },

  { id: "fqs-093", s: "fiqh", g: 4, d: 5, t: ["eid", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Qudūrī, al-Mukhtaṣar, bāb ṣalāt al-ʿīdayn",
    en: ["In the Ḥanafī school, how many additional takbīrs (zawāʾid) are said in each rakʿa of the ʿĪd prayer?", ["Three in each rakʿa", "Seven in the first, five in the second", "Six in the first, five in the second", "Five in each rakʿa"], "The Ḥanafīs follow Ibn Masʿūd: three extra takbīrs in each rakʿa, before recitation in the first and after it in the second. The Shāfiʿīs say seven and five, and the Mālikīs and Ḥanbalīs six and five."],
    de: ["Wie viele zusätzliche Takbīrs (zawāʾid) werden in der ḥanafitischen Schule in jeder Rakʿa des ʿĪd-Gebets gesprochen?", ["Drei in jeder Rakʿa", "Sieben in der ersten, fünf in der zweiten", "Sechs in der ersten, fünf in der zweiten", "Fünf in jeder Rakʿa"], "Die Ḥanafiten folgen Ibn Masʿūd: drei zusätzliche Takbīrs in jeder Rakʿa, in der ersten vor, in der zweiten nach der Rezitation. Die Šāfiʿiten sagen sieben und fünf, Mālikiten und Ḥanbaliten sechs und fünf."],
    ar: ["كم التكبيرات الزوائد في كل ركعة من صلاة العيد عند الحنفية؟", ["ثلاث في كل ركعة", "سبع في الأولى وخمس في الثانية", "ست في الأولى وخمس في الثانية", "خمس في كل ركعة"], "أخذ الحنفية بقول ابن مسعود: ثلاث زوائد في كل ركعة، قبل القراءة في الأولى وبعدها في الثانية، وعند الشافعية سبع وخمس، وعند المالكية والحنابلة ست وخمس."] },

  { id: "fqs-094", s: "fiqh", g: 4, d: 5, t: ["janazah", "madhhab-comparison"], tr: ["shafii", "hanbali", "comparative"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Janāʾiz, on praying over the absent",
    en: ["Which pair of schools permits the funeral prayer in absentia (ṣalāt al-ghāʾib), citing the Prophet's ﷺ prayer for the Negus (al-Najāshī)?", ["Shāfiʿī and Ḥanbalī", "Ḥanafī and Mālikī", "Ḥanafī and Shāfiʿī", "Mālikī and Ḥanbalī"], "The Shāfiʿīs and Ḥanbalīs allow praying over an absent body, based on the prayer for al-Najāshī. The Ḥanafīs and Mālikīs do not, treating that event as particular to him."],
    de: ["Welche beiden Schulen erlauben das Totengebet in Abwesenheit (ṣalāt al-ġāʾib) unter Berufung auf das Gebet des Propheten ﷺ für den Negus (an-Naǧāšī)?", ["Šāfiʿiten und Ḥanbaliten", "Ḥanafiten und Mālikiten", "Ḥanafiten und Šāfiʿiten", "Mālikiten und Ḥanbaliten"], "Šāfiʿiten und Ḥanbaliten erlauben das Gebet über einen abwesenden Leichnam aufgrund des Gebets für an-Naǧāšī. Ḥanafiten und Mālikiten lehnen es ab und sehen jenes Ereignis als Besonderheit."],
    ar: ["أيّ مذهبين يجيزان صلاة الغائب استدلالًا بصلاة النبي ﷺ على النجاشي؟", ["الشافعية والحنابلة", "الحنفية والمالكية", "الحنفية والشافعية", "المالكية والحنابلة"], "أجاز الشافعية والحنابلة الصلاة على الغائب لصلاة النبي ﷺ على النجاشي، ومنعها الحنفية والمالكية وعدّوا ذلك خصوصية."] },

  { id: "fqs-095", s: "fiqh", g: 4, d: 5, t: ["janazah", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Janāʾiz, on the martyr",
    en: ["A martyr killed in battle is not washed, by agreement. Which school holds that the funeral prayer is nevertheless performed over him?", ["Ḥanafī", "Mālikī", "Shāfiʿī", "Ḥanbalī"], "The Ḥanafīs pray over the battlefield martyr, citing reports of prayer over the martyrs of Uḥud. The Mālikīs, Shāfiʿīs and Ḥanbalīs (relied-upon view) do not, citing Jābir's report that they were neither washed nor prayed over."],
    de: ["Ein im Kampf gefallener Märtyrer wird nach Übereinstimmung nicht gewaschen. Welche Schule hält, dass dennoch das Totengebet über ihn verrichtet wird?", ["Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Ḥanafiten beten über den Gefallenen und verweisen auf Berichte über das Gebet für die Märtyrer von Uḥud. Mālikiten, Šāfiʿiten und Ḥanbaliten (maßgebliche Ansicht) tun es nicht, gestützt auf Ǧābirs Bericht, dass sie weder gewaschen noch über sie gebetet wurde."],
    ar: ["شهيد المعركة لا يُغسّل باتفاق. أيّ مذهب يرى أنه يُصلّى عليه مع ذلك؟", ["الحنفية", "المالكية", "الشافعية", "الحنابلة"], "يصلي الحنفية على شهيد المعركة لما رُوي من الصلاة على شهداء أحد، ولا يصلي عليه المالكية والشافعية والحنابلة في المعتمد لحديث جابر أنهم لم يُغسّلوا ولم يُصلَّ عليهم."] },

  { id: "fqs-096", s: "fiqh", g: 4, d: 5, t: ["congregation", "imamah", "madhhab-comparison"], tr: ["hanbali", "comparative"], src: "Ibn Qudāma, ʿUmdat al-Fiqh, bāb al-imāma; Muslim, Ṣaḥīḥ, hadith of Abū Masʿūd al-Anṣārī",
    en: ["Which school, taking the hadith of Abū Masʿūd ('the one who best recites leads') at face value, gives precedence in leading the prayer to the best reciter over the most learned in fiqh?", ["Ḥanbalī", "Ḥanafī", "Mālikī", "Shāfiʿī"], "The Ḥanbalīs put the best reciter who knows the rulings of prayer first. The relied-upon views of the Ḥanafīs, Mālikīs and Shāfiʿīs put the most learned in fiqh first, since the needs of the prayer depend more on fiqh."],
    de: ["Welche Schule gibt, den Hadith von Abū Masʿūd („es leitet, wer am besten rezitiert“) wörtlich nehmend, beim Vorbeten dem besten Rezitator den Vorrang vor dem Fiqh-Kundigsten?", ["Die ḥanbalitische", "Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische"], "Die Ḥanbaliten stellen den besten Rezitator, der die Gebetsregeln kennt, voran. Die maßgeblichen Ansichten der Ḥanafiten, Mālikiten und Šāfiʿiten stellen den Fiqh-Kundigsten voran, da die Erfordernisse des Gebets stärker vom Fiqh abhängen."],
    ar: ["أيّ مذهب يقدّم في الإمامة الأقرأ على الأفقه أخذًا بظاهر حديث أبي مسعود في تقديم أقرئهم لكتاب الله؟", ["الحنابلة", "الحنفية", "المالكية", "الشافعية"], "يقدّم الحنابلة الأجود قراءة العالم بفقه صلاته، والمعتمد عند الحنفية والمالكية والشافعية تقديم الأفقه لأن حاجة الصلاة إلى الفقه أكثر."] },

  { id: "fqs-097", s: "fiqh", g: 4, d: 5, t: ["congregation", "madhhab-comparison"], tr: ["hanbali", "comparative"], src: "Ibn Qudāma, al-Mughnī, Kitāb al-Ṣalāt, on praying alone behind the row",
    en: ["A man prays a full rakʿa alone behind the row without an excuse. Which school holds that his prayer is invalid?", ["Ḥanbalī", "Ḥanafī", "Mālikī", "Shāfiʿī"], "The Ḥanbalīs act on the hadith of Wābiṣa, in which the Prophet ﷺ ordered such a man to repeat his prayer. The other three schools consider the prayer valid but disliked."],
    de: ["Ein Mann betet ohne Entschuldigung eine ganze Rakʿa allein hinter der Reihe. Welche Schule hält sein Gebet für ungültig?", ["Die ḥanbalitische", "Die ḥanafitische", "Die mālikitische", "Die šāfiʿitische"], "Die Ḥanbaliten folgen dem Hadith von Wābiṣa, in dem der Prophet ﷺ einen solchen Mann sein Gebet wiederholen ließ. Die anderen drei Schulen halten das Gebet für gültig, aber verpönt."],
    ar: ["صلّى رجل خلف الصف وحده ركعة كاملة بلا عذر. أيّ مذهب يرى بطلان صلاته؟", ["الحنابلة", "الحنفية", "المالكية", "الشافعية"], "أخذ الحنابلة بحديث وابصة في أمر النبي ﷺ من صلى خلف الصف وحده بالإعادة، وصحّحها الثلاثة مع الكراهة."] },

  { id: "fqs-098", s: "fiqh", g: 4, d: 5, t: ["tashahhud", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Mālik, al-Muwaṭṭaʾ, Kitāb al-Ṣalāt, bāb al-tashahhud",
    en: ["Which wording of the tashahhud did Imam Mālik choose, recording it in al-Muwaṭṭaʾ?", ["The tashahhud of ʿUmar ibn al-Khaṭṭāb", "The tashahhud of Ibn Masʿūd", "The tashahhud of Ibn ʿAbbās", "The tashahhud of Abū Mūsā al-Ashʿarī"], "Mālik chose the tashahhud that ʿUmar taught people from the minbar. Abū Ḥanīfa and Aḥmad preferred that of Ibn Masʿūd, and al-Shāfiʿī that of Ibn ʿAbbās in Ṣaḥīḥ Muslim; all are valid."],
    de: ["Welche Fassung des Tašahhud wählte Imām Mālik und hielt sie in al-Muwaṭṭaʾ fest?", ["Den Tašahhud von ʿUmar ibn al-Ḫaṭṭāb", "Den Tašahhud von Ibn Masʿūd", "Den Tašahhud von Ibn ʿAbbās", "Den Tašahhud von Abū Mūsā al-Ašʿarī"], "Mālik wählte den Tašahhud, den ʿUmar die Leute von der Kanzel lehrte. Abū Ḥanīfa und Aḥmad bevorzugten den von Ibn Masʿūd, aš-Šāfiʿī den von Ibn ʿAbbās in Ṣaḥīḥ Muslim; alle sind gültig."],
    ar: ["أيّ صيغة للتشهد اختارها الإمام مالك وأوردها في الموطأ؟", ["تشهد عمر بن الخطاب", "تشهد ابن مسعود", "تشهد ابن عباس", "تشهد أبي موسى الأشعري"], "اختار مالك تشهد عمر الذي كان يعلّمه الناس على المنبر، واختار أبو حنيفة وأحمد تشهد ابن مسعود، والشافعي تشهد ابن عباس عند مسلم، وكلها جائزة."] },

  { id: "fqs-099", s: "fiqh", g: 4, d: 5, t: ["salah-sunan", "tashahhud", "madhhab-comparison"], tr: ["maliki", "comparative"], src: "Ibn Rushd, Bidāyat al-Mujtahid, Kitāb al-Ṣalāt, on the manner of sitting",
    en: ["Which school holds that tawarruk (sitting on the left hip with the left foot under the right shin) is the sunna for every sitting of the prayer?", ["Mālikī", "Ḥanafī", "Shāfiʿī", "Ḥanbalī"], "The Mālikīs sit in tawarruk in all sittings. The Ḥanafīs sit in iftirāsh in all (for men), the Shāfiʿīs use tawarruk in the last sitting of every prayer, and the Ḥanbalīs only in the last sitting of prayers with two tashahhuds."],
    de: ["Welche Schule hält Tawarruk (Sitzen auf der linken Hüfte, der linke Fuß unter dem rechten Schienbein) für die Sunna jedes Sitzens im Gebet?", ["Die mālikitische", "Die ḥanafitische", "Die šāfiʿitische", "Die ḥanbalitische"], "Die Mālikiten sitzen in allen Sitzungen im Tawarruk. Die Ḥanafiten sitzen (für Männer) immer im Iftirāš, die Šāfiʿiten nutzen Tawarruk im letzten Sitzen jedes Gebets, die Ḥanbaliten nur im letzten Sitzen von Gebeten mit zwei Tašahhuds."],
    ar: ["أيّ مذهب يسنّ التورك في جميع جلسات الصلاة؟", ["المالكية", "الحنفية", "الشافعية", "الحنابلة"], "يتورك المالكية في جميع الجلسات، ويفترش الحنفية فيها كلها للرجل، ويتورك الشافعية في التشهد الأخير من كل صلاة، والحنابلة في الأخير من الصلاة ذات التشهدين فقط."] },

  { id: "fqs-100", s: "fiqh", g: 4, d: 5, t: ["jumuah", "masbuq", "madhhab-comparison"], tr: ["hanafi", "comparative"], src: "al-Marghīnānī, al-Hidāya, bāb ṣalāt al-jumuʿa",
    en: ["A latecomer catches the imam of Jumuʿa only in the final tashahhud. Which jurists held that he completes two rakʿas as Jumuʿa rather than praying Ẓuhr?", ["Abū Ḥanīfa and Abū Yūsuf", "Muḥammad and al-Shāfiʿī", "Mālik and Aḥmad", "al-Shāfiʿī and Aḥmad"], "Abū Ḥanīfa and Abū Yūsuf held that catching any part of the imam's prayer is catching Jumuʿa. Muḥammad, with Mālik, al-Shāfiʿī and Aḥmad, requires catching a full rakʿa; otherwise he prays four for Ẓuhr."],
    de: ["Ein Nachzügler erreicht den Imam der Ǧumuʿa erst im letzten Tašahhud. Welche Juristen hielten, dass er zwei Rakʿas als Ǧumuʿa vollendet und nicht Ẓuhr betet?", ["Abū Ḥanīfa und Abū Yūsuf", "Muḥammad und aš-Šāfiʿī", "Mālik und Aḥmad", "aš-Šāfiʿī und Aḥmad"], "Abū Ḥanīfa und Abū Yūsuf hielten, wer irgendeinen Teil des Gebets des Imams erreicht, hat die Ǧumuʿa erreicht. Muḥammad verlangt mit Mālik, aš-Šāfiʿī und Aḥmad eine volle Rakʿa; sonst betet er vier Rakʿas Ẓuhr."],
    ar: ["أدرك المسبوق إمام الجمعة في التشهد الأخير فقط. مَن مِن الفقهاء قال إنه يتمها جمعة ركعتين لا ظهرًا؟", ["أبو حنيفة وأبو يوسف", "محمد والشافعي", "مالك وأحمد", "الشافعي وأحمد"], "يرى أبو حنيفة وأبو يوسف أن من أدرك الإمام في أي جزء من صلاته فقد أدرك الجمعة، واشترط محمد مع مالك والشافعي وأحمد إدراك ركعة كاملة وإلا صلى ظهرًا أربعًا."] },
];
